-- Generated from tripto_to_tax_refund_249_v1.json. Do not hand-edit country rows.
CREATE TABLE IF NOT EXISTS tax_refund_country_guides (
  iso2 TEXT PRIMARY KEY, iso3 TEXT NOT NULL, destination TEXT NOT NULL, refund_status TEXT NOT NULL,
  tax_type TEXT, standard_tax_rate TEXT, minimum_purchase TEXT, eligibility TEXT NOT NULL,
  eligible_purchases TEXT, excluded_purchases TEXT, export_deadline TEXT, at_purchase TEXT NOT NULL,
  departure_process TEXT NOT NULL, refund_method_fees TEXT, future_change TEXT, traveler_summary TEXT NOT NULL,
  source_quality TEXT NOT NULL, source_url_primary TEXT NOT NULL, source_url_secondary TEXT,
  last_verified_at TEXT NOT NULL, confidence TEXT NOT NULL, manual_review_required TEXT NOT NULL,
  app_display_policy TEXT NOT NULL, status_label TEXT NOT NULL, data_version TEXT NOT NULL,
  stale_after_days INTEGER NOT NULL, refresh_before_trip TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_tax_refund_country_guides_status ON tax_refund_country_guides(refund_status,confidence);
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('AF','AFG','Afghanistan','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Afghanistan: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('AL','ALB','Albania','AVAILABLE_LIMITED','VAT','20%','Country/participating-store minimum applies; verify current threshold','Eligible nonresident visitors shopping at participating Tax Free registered retailers.','Qualifying goods exported by the traveler.','Scheme exclusions apply.','Typically within 90 days under current guidance.','Request Tax Free voucher/document from a participating retailer.','Present goods, passport and Tax Free voucher at the Customs departure point.','Operator/merchant fees may reduce refund.',NULL,'Albania: tourist Tax Free shopping is available through participating registered retailers, but it is not as universally standardized as the major EU schemes. Ask for the Tax Free voucher in the shop, keep the goods and passport, and obtain Customs export validation—typically within 90 days. The current minimum spend should be refreshed before display.','Current 2026 secondary country reference','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show participating-store availability; threshold dynamic.','Available with important limitations','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('DZ','DZA','Algeria','NO_SCHEME_CONFIRMED',NULL,NULL,NULL,'No dedicated nationwide tourist VAT-refund scheme confirmed.',NULL,NULL,NULL,'Do not buy on the assumption that ordinary retail tax will be refunded at departure.','No standard nationwide tourist retail tax-refund departure procedure is confirmed.',NULL,NULL,'Algeria: No dedicated nationwide tourist VAT-refund scheme confirmed. Ordinary shopping taxes, where applicable, should generally be treated as part of the purchase price. Duty-free airport/port shopping and business/diplomatic refund rules are separate. Recheck local rules before a high-value purchase because local programs can change.','Current official/secondary check','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show ''No standard tourist refund confirmed'' with update date.','No standard tourist refund confirmed','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('AS','ASM','American Samoa','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'American Samoa has local tax rules; no standard nationwide tourist refund should be assumed.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'American Samoa: American Samoa has local tax rules; no standard nationwide tourist refund should be assumed. A reliable ordinary tourist retail refund workflow was not confirmed for this dataset. tripto.to should not inherit the parent country''s tax-free rules automatically; it should show ''Check local rules'' until a local tax/customs source is verified.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Territory-specific rule required; never auto-copy parent country.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('AD','AND','Andorra','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Andorra: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('AO','AGO','Angola','NO_SCHEME_CONFIRMED',NULL,NULL,NULL,'No dedicated nationwide tourist VAT-refund scheme confirmed.',NULL,NULL,NULL,'Do not buy on the assumption that ordinary retail tax will be refunded at departure.','No standard nationwide tourist retail tax-refund departure procedure is confirmed.',NULL,NULL,'Angola: No dedicated nationwide tourist VAT-refund scheme confirmed. Ordinary shopping taxes, where applicable, should generally be treated as part of the purchase price. Duty-free airport/port shopping and business/diplomatic refund rules are separate. Recheck local rules before a high-value purchase because local programs can change.','Current official/secondary check','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show ''No standard tourist refund confirmed'' with update date.','No standard tourist refund confirmed','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('AI','AIA','Anguilla','NO_GENERAL_VAT_GST','No broad VAT/GST (other duties/taxes may apply)',NULL,NULL,'No classic VAT system; local goods/services taxes can apply, but no departure VAT refund should be assumed.',NULL,NULL,NULL,'There is generally no VAT/GST departure refund to request. Check item-specific duties/excise and local retail taxes.','No standard VAT/GST refund process.',NULL,NULL,'Anguilla: No classic VAT system; local goods/services taxes can apply, but no departure VAT refund should be assumed. Because there is no broad VAT/GST of the usual kind to reclaim, there is generally no tourist departure VAT refund process. This does not mean every purchase is tax-free: customs duty, excise, local levies or sector taxes may still be built into the price.','Current tax-structure cross-check; territory-specific review recommended','https://vatinfo.org/countries-with-no-vat','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM','YES','Show ''No VAT/GST refund to claim''; avoid saying ''tax-free country''.','No broad VAT/GST refund to claim','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('AQ','ATA','Antarctica','NOT_APPLICABLE','Not applicable / no ordinary retail tourist system',NULL,NULL,'Antarctica has no normal nationwide retail/tax authority system for tourist shopping.',NULL,NULL,NULL,'No standard tourist shopping refund flow.','No standard refund flow.',NULL,NULL,'Antarctica: Antarctica has no normal nationwide retail/tax authority system for tourist shopping. A normal VAT/GST tourist-refund workflow is therefore not applicable. Any purchases made through expedition, base, ship or concession operators follow their own pricing/tax arrangements.','Jurisdiction characteristics; not a consumer tax-refund destination','https://www.iso.org/iso-3166-country-codes.html',NULL,'2026-09-27','HIGH','NO','Show ''Not applicable'' rather than ''No''.','Not applicable','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('AG','ATG','Antigua and Barbuda','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Antigua and Barbuda: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('AR','ARG','Argentina','AVAILABLE','VAT','21%','ARS 70 minimum under the legal scheme; nominal threshold is extremely low and should not be presented as economically meaningful','Foreign tourists buying eligible Argentine-produced goods from participating Tax Free shops.','Taxed goods produced in Argentina, purchased from participating merchants.','Imported goods and purchases outside the participating regime.','Claim/validate when leaving Argentina; current process includes electronic/self-service validation.','Show passport/accepted tourist proof; request the required class-B invoice/e-ticket and electronic refund check from a participating merchant.','At departure use the assigned self-service/electronic validation process and Customs inspection if required, then complete refund through the operator.','VAT is refunded less the authorized operator''s administrative commission; cash/card/other operator methods may be available.',NULL,'Argentina: foreign tourists can recover VAT on eligible Argentine-made goods bought at participating Tax Free stores. The legal minimum is ARS 70, but that is a legacy nominal threshold and should not be emphasized as a practical shopping target. Ask for the correct invoice and refund check, keep the goods, and complete electronic/Customs validation when leaving.','Official Argentina government / ARCA; 2026 procedure update','https://www.argentina.gob.ar/servicio/reintegrar-impuestos-turistas-extranjeros','https://www.boletinoficial.gov.ar/detalleAviso/primera/341629/20260506','2026-09-27','HIGH','NO','Show available; de-emphasize obsolete-looking nominal ARS70 threshold.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('AM','ARM','Armenia','AVAILABLE_LIMITED','VAT','20%','Current participating-store minimum applies; verify before trip','Eligible nonresident tourists shopping at participating Tax Free stores.','Qualifying goods exported by traveler.','Scheme exclusions apply.','Follow current Armenian Customs/export-validation deadline.','Use a participating Tax Free shop and obtain refund documentation.','Present goods, passport and forms at departure Customs/refund point.','Operator/refund fees may apply.',NULL,'Armenia: a tourist Tax Free VAT-refund scheme is available through participating shops. Ask for the Tax Free documents at purchase and keep the goods and passport for Customs validation on departure. Because the practical minimum and operator coverage can change, tripto.to should refresh those fields rather than hard-code an old threshold.','Current 2026 secondary country reference','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show available at participating shops; refresh threshold.','Available with important limitations','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('AW','ABW','Aruba','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'Aruba has its own turnover/consumption taxes; do not copy Netherlands/EU rules.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Aruba: Aruba has its own turnover/consumption taxes; do not copy Netherlands/EU rules. A reliable ordinary tourist retail refund workflow was not confirmed for this dataset. tripto.to should not inherit the parent country''s tax-free rules automatically; it should show ''Check local rules'' until a local tax/customs source is verified.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Territory-specific rule required; never auto-copy parent country.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('AU','AUS','Australia','AVAILABLE','GST/WET','GST 10%','AUD 300 total from the same ABN; purchases within 60 days before departure','Eligible departing travelers who buy qualifying goods in Australia and take them out of Australia.','Qualifying goods carried/worn as accompanied baggage; valid tax invoice required.','Services, goods consumed in Australia, freighted goods, and other TRS exclusions.','Purchase must be within 60 days before departure; claim when leaving Australia.','Obtain a valid tax invoice. Purchases from businesses using the same ABN can be combined to reach AUD 300.','Claim through the Tourist Refund Scheme at the international departure point; allow time for goods/document inspection.','Government TRS refunds eligible GST/WET; refund method depends on TRS options.',NULL,'Australia: the Tourist Refund Scheme (TRS) can refund GST/WET on qualifying goods. Spend at least AUD 300 in total with businesses using the same ABN and buy within 60 days before departure. Keep valid tax invoices and the goods available for inspection, then make the claim at international departure. Services and goods consumed in Australia do not qualify.','Official border authority','https://www.abf.gov.au/entering-and-leaving-australia/tourist-refund-scheme',NULL,'2026-09-27','HIGH','NO','Show ''TRS available'' with AUD 300 / 60-day rule.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('AT','AUT','Austria','AVAILABLE','VAT','20%','€75.01','Habitual residence outside the EU; proof of residence/identity required. Retailer participation and local rules apply.','Qualifying goods for personal/non-commercial use that leave the EU in the traveler''s baggage.','Services and goods not exported; commercial quantities and other locally excluded categories.','Normally within 3 months of purchase; obtain customs/export validation at the final EU exit point.','Ask for the country''s tax-free/VAT-refund document and present passport or other accepted proof of non-EU residence.','Present goods, receipts and refund documents for customs/electronic validation at the final EU departure point; follow checked-baggage rules.','Retailer or authorized intermediary refunds the VAT; fees/commissions may reduce the amount received.',NULL,'Austria: tourist VAT refund is available for eligible travelers whose habitual residence is outside the EU. Standard VAT rate: 20%. Typical minimum purchase requirement: €75.01 (per invoice/qualifying purchase). Buy from a retailer that supports tax-free sales, show proof of non-EU residence, keep the goods, receipt and tax-free document, and obtain customs/export validation when you leave the EU. The goods must normally leave the EU within 3 months of purchase. Services and goods consumed before export generally do not qualify. Refund operators may deduct fees.','Official EU framework; country threshold/rate cross-checked where available','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show ''Tax refund available''; keep threshold/source date visible.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('AZ','AZE','Azerbaijan','AVAILABLE','VAT','18%','AZN 300 including VAT per e-tax invoice','Eligible foreign visitors using participating Tax Free stores.','Qualifying goods bought from Tax Free merchants and exported by air.','Excisable goods, food, medicines, precious stones/metals, vehicles and other exclusions.','Export by air within 90 days.','Use participating Tax Free store and obtain the electronic tax-free invoice/document.','Complete airport/customs validation with goods and passport.','Current scheme guidance indicates about 80% of the VAT amount is returned after a 20% service deduction.',NULL,'Azerbaijan: Tax Free shopping is available at participating stores. Spend at least AZN 300 including VAT per e-tax invoice, keep the goods and documents, and export them by air within 90 days. Excisable goods, food, medicines, precious stones/metals and vehicles are excluded. The service keeps part of the VAT, so the payout is below the full tax.','Current 2026 country reference; production should link official tax page when refreshed','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM-HIGH','YES','Show available + AZN300 + air departure.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('BS','BHS','Bahamas','AVAILABLE','VAT','10%','US$25 minimum for eligible non-consumable items under current tourism guidance','Non-Bahamian residents meeting visitor/refund conditions.','Eligible non-consumable goods bought through the Tax Free system.','Special rules apply to alcohol/tobacco/rum cakes; other excluded items apply.','Current tourism guidance requires departure within 45 days for the visitor Tax Free conditions.','Use participating Global Blue Tax Free retailers and present required travel identification.','Follow departure validation; special categories may be limited to Nassau airport rules.','Tax-free/refund handled through the participating operator.',NULL,'Bahamas: qualifying visitors can use the Tax Free system at participating retailers. The current tourist guidance uses a US$25 minimum for eligible non-consumable goods and a 45-day visitor/departure condition. Alcohol, tobacco and some food items have special rules, so tripto.to should show category-specific notes rather than one blanket rule.','Official Bahamas tourism guidance','https://www.bahamas.com/plan-your-trip/island-faq',NULL,'2026-09-27','HIGH','YES','Show available + category exceptions.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('BH','BHR','Bahrain','AVAILABLE','VAT','10%','Confirm current participating-retailer threshold','Eligible overseas tourists using participating Tax Free retailers/operator.','Qualifying goods under Bahrain''s Tax Free scheme.','Scheme exclusions apply.','Follow current operator/export-validation rules.','Use a participating Tax Free store and request the Tax Free form/transaction.','Validate at the authorized departure process and keep goods/passport/forms available.','Operator fees reduce the payout.',NULL,'Bahrain: an active tourist Tax Free operation is listed by Planet in 2026, with a 10% VAT rate. Use participating stores, request the Tax Free transaction at purchase, and complete departure validation with the goods and passport. The exact current minimum-spend and operator-fee details should be refreshed before displaying them as fixed numbers.','Current authorized refund-operator destination listing','https://taxfree.weareplanet.com/countries','https://www.weareplanet.com/legal/products-terms-and-conditions','2026-09-27','MEDIUM-HIGH','YES','Show available; threshold should be remotely refreshable.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('BD','BGD','Bangladesh','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Bangladesh: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
