INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('BN','BRN','Brunei Darussalam','NO_GENERAL_VAT_GST','No broad VAT/GST (other duties/taxes may apply)',NULL,NULL,'No broad VAT/GST on ordinary retail purchases.',NULL,NULL,NULL,'There is generally no VAT/GST departure refund to request. Check item-specific duties/excise and local retail taxes.','No standard VAT/GST refund process.',NULL,NULL,'Brunei Darussalam: No broad VAT/GST on ordinary retail purchases. Because there is no broad VAT/GST of the usual kind to reclaim, there is generally no tourist departure VAT refund process. This does not mean every purchase is tax-free: customs duty, excise, local levies or sector taxes may still be built into the price.','Current tax-structure cross-check; territory-specific review recommended','https://vatinfo.org/countries-with-no-vat','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM','YES','Show ''No VAT/GST refund to claim''; avoid saying ''tax-free country''.','No broad VAT/GST refund to claim','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('BG','BGR','Bulgaria','AVAILABLE','VAT','20%','BGN 250','Habitual residence outside the EU; proof of residence/identity required. Retailer participation and local rules apply.','Qualifying goods for personal/non-commercial use that leave the EU in the traveler''s baggage.','Services and goods not exported; commercial quantities and other locally excluded categories.','Normally within 3 months of purchase; obtain customs/export validation at the final EU exit point.','Ask for the country''s tax-free/VAT-refund document and present passport or other accepted proof of non-EU residence.','Present goods, receipts and refund documents for customs/electronic validation at the final EU departure point; follow checked-baggage rules.','Retailer or authorized intermediary refunds the VAT; fees/commissions may reduce the amount received.',NULL,'Bulgaria: tourist VAT refund is available for eligible travelers whose habitual residence is outside the EU. Standard VAT rate: 20%. Typical minimum purchase requirement: BGN 250 (per qualifying purchase). Buy from a retailer that supports tax-free sales, show proof of non-EU residence, keep the goods, receipt and tax-free document, and obtain customs/export validation when you leave the EU. The goods must normally leave the EU within 3 months of purchase. Services and goods consumed before export generally do not qualify. Refund operators may deduct fees.','Official EU framework; country threshold/rate cross-checked where available','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show ''Tax refund available''; keep threshold/source date visible.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('BF','BFA','Burkina Faso','NO_SCHEME_CONFIRMED',NULL,NULL,NULL,'No dedicated nationwide tourist VAT-refund scheme confirmed.',NULL,NULL,NULL,'Do not buy on the assumption that ordinary retail tax will be refunded at departure.','No standard nationwide tourist retail tax-refund departure procedure is confirmed.',NULL,NULL,'Burkina Faso: No dedicated nationwide tourist VAT-refund scheme confirmed. Ordinary shopping taxes, where applicable, should generally be treated as part of the purchase price. Duty-free airport/port shopping and business/diplomatic refund rules are separate. Recheck local rules before a high-value purchase because local programs can change.','Current official/secondary check','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show ''No standard tourist refund confirmed'' with update date.','No standard tourist refund confirmed','tripto.to-tax-refund-v1.0',90,'YES');
