INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('CL','CHL','Chile','NO_SCHEME_CONFIRMED',NULL,NULL,NULL,'No ordinary nationwide retail VAT refund for tourists; some tourism/accommodation tax treatment is separate.',NULL,NULL,NULL,'Do not buy on the assumption that ordinary retail tax will be refunded at departure.','No standard nationwide tourist retail tax-refund departure procedure is confirmed.',NULL,NULL,'Chile: No ordinary nationwide retail VAT refund for tourists; some tourism/accommodation tax treatment is separate. Ordinary shopping taxes, where applicable, should generally be treated as part of the purchase price. Duty-free airport/port shopping and business/diplomatic refund rules are separate. Recheck local rules before a high-value purchase because local programs can change.','Current official/secondary check','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show ''No standard tourist refund confirmed'' with update date.','No standard tourist refund confirmed','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('CN','CHN','China','AVAILABLE','VAT','13% standard for many goods; refund scheme uses category-specific rates','CNY 200 at the same store on the same day','Eligible overseas visitors under China''s departure tax-refund rules, buying from designated tax-refund stores.','Eligible unused goods carried out of China by the traveler.','Consumed/non-exported goods and excluded categories.','Goods generally must be exported within 90 days of purchase.','Buy from designated tax-refund stores and obtain the required VAT invoice/refund application information.','Present goods, passport/travel documents and tax-refund paperwork at an eligible departure port/customs point.','Refund rate commonly 11% for goods taxed at 13%, less agency handling; cash refund has a CNY 20,000 cap under current rules.',NULL,'China: departure VAT refunds are available at designated tax-refund stores. Current rules lowered the minimum to CNY 200 at the same store on the same day. Keep the goods unused, retain the required invoice/refund documents, and export the goods within 90 days through an eligible departure point. The net refund is lower than the headline VAT because agency handling is deducted.','Current legal/secondary cross-check; verify departure-port coverage','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM-HIGH','YES','Show available, but keep ''eligible departure port'' warning.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('CX','CXR','Christmas Island','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'Christmas Island tax treatment can depend on Australian rules; tourist-refund applicability must be confirmed.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Christmas Island: Christmas Island tax treatment can depend on Australian rules; tourist-refund applicability must be confirmed. A reliable ordinary tourist retail refund workflow was not confirmed for this dataset. tripto.to should not inherit the parent country''s tax-free rules automatically; it should show ''Check local rules'' until a local tax/customs source is verified.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Territory-specific rule required; never auto-copy parent country.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('CC','CCK','Cocos (Keeling) Islands','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'Cocos (Keeling) Islands tax treatment can depend on Australian rules; tourist-refund applicability must be confirmed.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Cocos (Keeling) Islands: Cocos (Keeling) Islands tax treatment can depend on Australian rules; tourist-refund applicability must be confirmed. A reliable ordinary tourist retail refund workflow was not confirmed for this dataset. tripto.to should not inherit the parent country''s tax-free rules automatically; it should show ''Check local rules'' until a local tax/customs source is verified.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Territory-specific rule required; never auto-copy parent country.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('CO','COL','Colombia','AVAILABLE','VAT','19% standard; refund applies to qualifying taxed goods','At least 3 UVT per electronic invoice','Foreign tourists of non-Colombian nationality meeting DIAN conditions.','Qualifying goods purchased with an electronic invoice in the tourist''s name.','Services and non-qualifying goods.','Claim when departing Colombia; goods/invoices must satisfy DIAN departure requirements.','Request an electronic invoice in the tourist''s name and identification/document number.','Apply personally at the DIAN traveler office before checking luggage; present goods and documentation as requested.','Refund is up to the VAT paid on eligible goods, subject to DIAN rules; maximum refund request is 200 UVT.',NULL,'Colombia: foreign tourists can request a VAT refund on qualifying goods. Each electronic invoice must reach at least 3 UVT, and the refund request is capped at 200 UVT. Make sure the electronic invoice is in your name, keep the goods, and apply personally at the DIAN traveler office when leaving—before checking luggage.','Official DIAN','https://www.dian.gov.co/Viajeros-y-Servicios-aduaneros/Paginas/Devolucion-IVA-a-Turistas-Extranjeros-Eng.aspx',NULL,'2026-09-27','HIGH','NO','Show available; display thresholds in UVT and explain UVT changes annually.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('KM','COM','Comoros','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Comoros: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
