INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('EC','ECU','Ecuador','AVAILABLE','VAT','Current VAT rate varies by policy period; refund applies to qualifying goods','Invoice taxable base of at least US$50','Eligible foreign tourists under SRI rules.','Qualifying locally produced goods bought from participating/authorized vendors.','Services and purchases outside the tourist-refund regime.','Claim at departure through the authorized airport process.','Request the qualifying invoice and keep passport/travel documentation.','Customs/SRI verification at Quito or Guayaquil airport under the current procedure.','Refund is made to supported international cards; current SRI procedure deducts an administrative fee (official materials cite US$3).',NULL,'Ecuador: eligible foreign tourists can claim VAT back on qualifying locally produced goods. The taxable base on the invoice must be at least US$50. Keep the invoice and goods, complete verification at the authorized airport departure process, and receive the refund to a supported payment card minus the administrative fee.','Official Ecuador SRI','https://www.sri.gob.ec/devolucion-del-iva-turistas-extranjeros',NULL,'2026-09-27','HIGH','NO','Show available + US$50 base + airport limitation.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('EG','EGY','Egypt','AVAILABLE','VAT','14%','EGP 1,500 per qualifying invoice','Eligible foreign visitors/tourists staying within the scheme''s permitted period.','Qualifying goods from participating VAT Refund retailers, exported with the traveler.','Services and items not carried out under the scheme.','Tourist stay/claim generally within 3 months under the current scheme.','Use a participating VAT Refund store; request the e-receipt/tax documentation and provide passport details.','Present passport, goods and qualifying purchase documentation at the airport tax-refund process before departure.','Refund is paid to an eligible foreign bank card under the current system.',NULL,'Egypt: a tourist VAT refund system is available for qualifying goods from participating stores. A qualifying invoice must be at least EGP 1,500. Keep the goods, passport and e-receipt/tax documents, and complete the airport refund process before departure. Refunds are paid to an eligible foreign bank card.','Official Egyptian Tax Authority','https://www.incometax.gov.eg/en/tax-refund',NULL,'2026-09-27','HIGH','NO','Show available + EGP 1,500.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
