INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('FO','FRO','Faroe Islands','AVAILABLE','VAT','25%','Participating-retailer minimum applies; confirm current amount','Eligible visitors under Faroe Islands Tax Free rules.','Qualifying goods from participating Tax Free retailers.','Scheme exclusions apply.','Follow current local export-validation rules.','Request Tax Free form/transaction from participating retailer.','Obtain required export/customs validation when leaving the Faroe Islands.','Operator fees reduce the refund.',NULL,'Faroe Islands: Tax Free shopping is available through participating retailers/operators, with a 25% VAT rate. The Faroe Islands are outside EU VAT territory, so do not apply Denmark/EU departure rules automatically. Ask for the local Tax Free form and complete the local export-validation process.','Current operator listing + official EU territorial-scope confirmation','https://taxfree.weareplanet.com/countries','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/how-does-vat-work/territorial-scope_en','2026-09-27','MEDIUM-HIGH','YES','Show as separate destination, not Denmark/EU rule.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('FJ','FJI','Fiji','AVAILABLE','VAT','15% standard (confirm current rate for item)','FJ$500 cumulative at approved retailers','Nonresident foreign-passport holder, generally age 13+, meeting Tourist VAT Refund Scheme conditions.','Eligible non-consumable goods bought from approved retailers, unused and in original packaging.','Consumables and other excluded categories.','Goods must generally be exported within 2 months from purchase.','Shop at approved TVRS retailers and retain Form 7 / tax documents, receipts and passport.','For checked baggage, complete validation before check-in; for hand luggage, follow the after-passport-control validation process. Scheme operates at designated airports/cruise terminals.','Refund paid under Fiji TVRS rules after validation.',NULL,'Fiji: the Tourist VAT Refund Scheme is available to qualifying nonresident visitors. You need at least FJ$500 in cumulative eligible purchases from approved retailers. Keep the goods unused and in original packaging, retain the required form and receipts, and complete validation when leaving. Checked-baggage goods must be handled before check-in.','Official Fiji Revenue and Customs Service','https://frcs.org.fj/our-services/customs/travellers/departing-the-country/tourist-vat-refund-scheme-tvrs/',NULL,'2026-09-27','HIGH','NO','Show available + FJ$500 cumulative.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
