INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('HM','HMD','Heard Island and McDonald Islands','NOT_APPLICABLE','Not applicable / no ordinary retail tourist system',NULL,NULL,'Heard Island and McDonald Islands have no ordinary resident retail economy.',NULL,NULL,NULL,'No standard tourist shopping refund flow.','No standard refund flow.',NULL,NULL,'Heard Island and McDonald Islands: Heard Island and McDonald Islands have no ordinary resident retail economy. A normal VAT/GST tourist-refund workflow is therefore not applicable. Any purchases made through expedition, base, ship or concession operators follow their own pricing/tax arrangements.','Jurisdiction characteristics; not a consumer tax-refund destination','https://www.iso.org/iso-3166-country-codes.html',NULL,'2026-09-27','HIGH','NO','Show ''Not applicable'' rather than ''No''.','Not applicable','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
