INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('HK','HKG','Hong Kong','NO_GENERAL_VAT_GST','No broad VAT/GST (other duties/taxes may apply)',NULL,NULL,'No VAT/GST or general sales tax on ordinary retail purchases.',NULL,NULL,NULL,'There is generally no VAT/GST departure refund to request. Check item-specific duties/excise and local retail taxes.','No standard VAT/GST refund process.',NULL,NULL,'Hong Kong: No VAT/GST or general sales tax on ordinary retail purchases. Because there is no broad VAT/GST of the usual kind to reclaim, there is generally no tourist departure VAT refund process. This does not mean every purchase is tax-free: customs duty, excise, local levies or sector taxes may still be built into the price.','Current tax-structure cross-check; territory-specific review recommended','https://vatinfo.org/countries-with-no-vat','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM','YES','Show ''No VAT/GST refund to claim''; avoid saying ''tax-free country''.','No broad VAT/GST refund to claim','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('HU','HUN','Hungary','AVAILABLE','VAT','27%','€175 / HUF 68,000 in 2026','Habitual residence outside the EU; proof of residence/identity required. Retailer participation and local rules apply.','Qualifying goods for personal/non-commercial use that leave the EU in the traveler''s baggage.','Services and goods not exported; commercial quantities and other locally excluded categories.','Normally within 3 months of purchase; obtain customs/export validation at the final EU exit point.','Ask for the country''s tax-free/VAT-refund document and present passport or other accepted proof of non-EU residence.','Present goods, receipts and refund documents for customs/electronic validation at the final EU departure point; follow checked-baggage rules.','Retailer or authorized intermediary refunds the VAT; fees/commissions may reduce the amount received.',NULL,'Hungary: tourist VAT refund is available for eligible travelers whose habitual residence is outside the EU. Standard VAT rate: 27%. Typical minimum purchase requirement: €175 / HUF 68,000 in 2026 (purchase amount must exceed this threshold). Buy from a retailer that supports tax-free sales, show proof of non-EU residence, keep the goods, receipt and tax-free document, and obtain customs/export validation when you leave the EU. The goods must normally leave the EU within 3 months of purchase. Services and goods consumed before export generally do not qualify. Refund operators may deduct fees.','Official EU framework; country threshold/rate cross-checked where available','https://nav.gov.hu/en/intormation_on_customs_matters/travel-guides---faq/english/vat-refunds-for-foreign-travellers','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','2026-09-27','HIGH','NO','Show ''Tax refund available''; keep threshold/source date visible.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('IS','ISL','Iceland','AVAILABLE','VAT','24%','ISK 6,000 on a qualifying receipt under current operator guidance','Eligible nonresident tourists under Iceland Tax Free rules.','Qualifying goods exported by the traveler.','Services/consumed goods and scheme exclusions.','Follow current Iceland export-validation deadline.','Request Tax Free documentation from a participating store.','Validate at Customs/refund point before departure with goods and documents available.','Operator commission reduces refund.',NULL,'Iceland: tourist Tax Free refunds are available for qualifying exported goods. Current 2026 guidance uses an ISK 6,000 minimum on a qualifying receipt. Ask for Tax Free paperwork in the store, keep the goods and receipt, and complete Customs/refund validation at departure. Operator fees reduce the amount you receive.','Current refund-operator/secondary cross-check','https://taxfree.weareplanet.com/countries','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show available + ISK 6,000; refresh periodically.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('IN','IND','India','NO_SCHEME_CONFIRMED',NULL,NULL,NULL,'No operational nationwide tourist GST-refund scheme for ordinary retail purchases confirmed.',NULL,NULL,NULL,'Do not buy on the assumption that ordinary retail tax will be refunded at departure.','No standard nationwide tourist retail tax-refund departure procedure is confirmed.',NULL,NULL,'India: No operational nationwide tourist GST-refund scheme for ordinary retail purchases confirmed. Ordinary shopping taxes, where applicable, should generally be treated as part of the purchase price. Duty-free airport/port shopping and business/diplomatic refund rules are separate. Recheck local rules before a high-value purchase because local programs can change.','Current official/secondary check','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show ''No standard tourist refund confirmed'' with update date.','No standard tourist refund confirmed','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('ID','IDN','Indonesia','AVAILABLE','VAT','Current VAT regime; tourist-refund qualifying invoices apply','Common current rule: at least IDR 500,000 per qualifying tax invoice and IDR 5,000,000 total refund purchases; verify threshold before trip','Eligible foreign passport holders under Indonesia''s tourist VAT-refund procedure.','Qualifying goods bought from participating VAT refund retailers and carried out of Indonesia.','Services/non-qualifying purchases and goods not exported.','Claim at a participating international airport when departing.','Obtain the special tax invoice/required purchase documentation and keep passport details linked correctly.','Submit/complete the online request as required, then show passport, boarding pass, goods and invoices at the VAT Refund counter.','Cash may be available at departure under limits; bank transfer is used for other cases and may take up to about one month.',NULL,'Indonesia: a tourist VAT-refund procedure operates at selected international airports. Keep the special tax invoices, passport and goods, complete the online/refund request, and present everything at the departure counter. Common current thresholds are IDR 500,000 per invoice and IDR 5,000,000 total, but tripto.to should verify those thresholds before each release because the official process page is clearer than the current threshold wording.','Official Indonesian tax authority for process; thresholds secondary','https://www.pajak.go.id/index.php/en/node/34252','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show available only at supported airports; threshold refresh required.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
