INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('IE','IRL','Ireland','AVAILABLE','VAT','23%',NULL,'Habitual residence outside the EU; proof of residence/identity required. Retailer participation and local rules apply.','Qualifying goods for personal/non-commercial use that leave the EU in the traveler''s baggage.','Services and goods not exported; commercial quantities and other locally excluded categories.','Normally within 3 months of purchase; obtain customs/export validation at the final EU exit point.','Ask for the country''s tax-free/VAT-refund document and present passport or other accepted proof of non-EU residence.','Present goods, receipts and refund documents for customs/electronic validation at the final EU departure point; follow checked-baggage rules.','Retailer or authorized intermediary refunds the VAT; fees/commissions may reduce the amount received.',NULL,'Ireland: tourist VAT refund is available for eligible travelers whose habitual residence is outside the EU. Standard VAT rate: 23%. A country-specific minimum/retailer condition applies; confirm it at the shop. Buy from a retailer that supports tax-free sales, show proof of non-EU residence, keep the goods, receipt and tax-free document, and obtain customs/export validation when you leave the EU. The goods must normally leave the EU within 3 months of purchase. Services and goods consumed before export generally do not qualify. Refund operators may deduct fees.','Official EU framework; country threshold/rate cross-checked where available','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show ''Tax refund available''; keep threshold/source date visible.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('IM','IMN','Isle of Man','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'Isle of Man is in the UK VAT/customs area arrangements but has its own administration; confirm visitor refund treatment locally rather than copying Great Britain.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Isle of Man: Isle of Man is in the UK VAT/customs area arrangements but has its own administration; confirm visitor refund treatment locally rather than copying Great Britain. A reliable ordinary tourist retail refund workflow was not confirmed for this dataset. tripto.to should not inherit the parent country''s tax-free rules automatically; it should show ''Check local rules'' until a local tax/customs source is verified.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Territory-specific rule required; never auto-copy parent country.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('IL','ISR','Israel','AVAILABLE','VAT','Standard VAT applies; eligible tourist goods may be refunded','₪186 including VAT on the purchase day','Tourists meeting Israeli VAT-law entry-status conditions (including qualifying B2/B3/B4 status); Israeli dual citizens are generally not eligible, with limited exceptions.','Personal-use goods in non-commercial quantities purchased from approved VAT-refund businesses and taken out of Israel.','Purchases from non-approved businesses and items not exported; special packaging rules apply to high-value jewelry/valuables.','Claim before leaving Israel; applications submitted from abroad are not accepted.','Use an approved business. Obtain the tax invoice and dedicated VAT-refund document; keep passport/entry documentation.','Present passport, goods, invoice and dedicated document at the Milgam VAT-refund point. If goods must be checked, validate them before security/check-in as instructed.','Current government page states a ₪27 service fee per dedicated document; cash also has a 1% + VAT fee, and bank transfer has a ₪47.5 fee. Refund can be cash, cheque or bank transfer.',NULL,'Israel: eligible tourists can claim VAT back on qualifying goods bought from approved businesses. Minimum purchase: ₪186 including VAT on the purchase day. Get the invoice and dedicated refund document in the shop, keep the goods and passport/entry proof, and complete the claim before leaving Israel. The refund service charges fees, so the amount received is lower than the VAT shown.','Official Israel Tax Authority / Ministry of Tourism','https://www.gov.il/en/pages/vat-refund-guide-for-tourists','https://www.gov.il/en/service/vat_tourists_refund','2026-09-27','HIGH','NO','Show available + exact minimum + fee warning.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('IT','ITA','Italy','AVAILABLE','VAT','22%','€70.01','Habitual residence outside the EU; proof of residence/identity required. Retailer participation and local rules apply.','Qualifying goods for personal/non-commercial use that leave the EU in the traveler''s baggage.','Services and goods not exported; commercial quantities and other locally excluded categories.','Normally within 3 months of purchase; obtain customs/export validation at the final EU exit point.','Ask for the country''s tax-free/VAT-refund document and present passport or other accepted proof of non-EU residence.','Present goods, receipts and refund documents for customs/electronic validation at the final EU departure point; follow checked-baggage rules.','Retailer or authorized intermediary refunds the VAT; fees/commissions may reduce the amount received.',NULL,'Italy: tourist VAT refund is available for eligible travelers whose habitual residence is outside the EU. Standard VAT rate: 22%. Typical minimum purchase requirement: €70.01 (per qualifying purchase). Buy from a retailer that supports tax-free sales, show proof of non-EU residence, keep the goods, receipt and tax-free document, and obtain customs/export validation when you leave the EU. The goods must normally leave the EU within 3 months of purchase. Services and goods consumed before export generally do not qualify. Refund operators may deduct fees.','Official EU framework; country threshold/rate cross-checked where available','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show ''Tax refund available''; keep threshold/source date visible.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('JM','JAM','Jamaica','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Jamaica: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('JP','JPN','Japan','AVAILABLE','Consumption tax','10% standard (reduced rate applies to some items)','¥5,000 before tax per store/day for the relevant product category under the current system','Eligible temporary visitors/nonresidents meeting Japan''s tax-free shopping conditions.','Qualifying general and consumable goods bought from authorized tax-free stores.','Items not meeting tax-free conditions; goods must be exported and purchase records are linked to passport information.','Current rules require export when leaving Japan; inspection can occur at customs.','Until 2026-10-31, eligible purchases can generally be sold tax-free at authorized shops after passport/eligibility verification.','Customs may inspect tax-free goods and passport-linked purchase records at departure.','Current system generally provides tax exemption at purchase rather than an airport refund.','IMPORTANT: from 2026-11-01 Japan changes to a refund-at-departure style system: shoppers pay tax at purchase and obtain a refund after export confirmation under the new rules.','Japan: as of 27 September 2026, the current tax-free-at-purchase system is still in force. Eligible visitors generally need at least ¥5,000 before tax per store/day and must shop at authorized tax-free stores. Keep the goods and passport available for departure checks. Important: Japan changes the system on 1 November 2026, so trips after that date need the new refund procedure.','Official/national tourism and tax-free reform guidance','https://www.mlit.go.jp/kankocho/en/tax-free/','https://www.japan.travel/en/plan/japans-tax-exemption/','2026-09-27','HIGH','NO','Show current rule with prominent 2026-11-01 future-change banner.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('JE','JEY','Jersey','AVAILABLE','GST','5%','More than £100 in a single approved retailer on the same day','Qualifying visitor, generally nonresident and within Jersey visitor-duration conditions; age 16+ under scheme rules.','Qualifying goods bought from approved retailers and taken out of Jersey.','Services and scheme-excluded goods.','Leave Jersey with the goods within 1 month of purchase under current scheme.','Buy from an approved retailer and obtain the GST refund documentation.','Complete the Global Blue/kiosk validation process at the airport/ferry departure as instructed; goods may need inspection.','Refund is handled by the scheme/operator and fees may apply.',NULL,'Jersey: visitors can claim GST back on qualifying goods bought from approved retailers. Spend more than £100 at one approved retailer on the same day and leave Jersey with the goods within 1 month. Keep receipts and goods, then complete the departure validation/refund process.','Official Government of Jersey','https://www.gov.je/taxesmoney/gst/gstcustomers/pages/gstrefundsvisitors.aspx',NULL,'2026-09-27','HIGH','NO','Show available + £100 + 1 month.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('JO','JOR','Jordan','AVAILABLE','General sales tax / VAT-style tax','16% standard','Tax amount on qualifying invoice/form must meet current scheme threshold; official tourism guidance cites JD 50 tax-value threshold','Eligible nonresident tourists; official guidance includes residence-outside-Jordan tests.','Qualifying goods from registered Tax Free merchants, exported by the tourist.','Non-qualifying/consumed goods and services outside the regime.','Claim on departure through authorized air/land/sea points.','Shop at registered Tax Free stores and obtain the original invoice/refund form.','Present goods, invoice/form and travel documents to Customs; refund operator process is available at authorized exit points.','Refund handled under the Tax Free operator process; method depends on amount/exit point.',NULL,'Jordan: a tourist tax-refund scheme is operating through registered Tax Free merchants and authorized departure points. Obtain the correct invoice/refund form in the shop, keep the goods and travel documents, and have Customs validate the export when leaving. Official tourism guidance uses a JD 50 tax-value threshold, so the app should show the threshold wording carefully rather than treating it as a purchase-price minimum.','Official Jordan tourism/government guidance','https://international.visitjordan.com/page/29/taxrefund/','https://www.istd.gov.jo/','2026-09-27','MEDIUM-HIGH','YES','Show available but flag threshold wording for periodic review.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('KZ','KAZ','Kazakhstan','PILOT','VAT','12% standard under pilot-era rules; verify current national rate','Pilot threshold reported around KZT 50,500; verify against the participating operator/current pilot notice','Non-EAEU foreign visitors meeting the Tax Free pilot conditions.','Qualifying non-food goods from participating pilot retailers.','Food and other excluded goods under pilot rules.','Pilot rules use a limited export window; current practical details should be confirmed.','Shop at participating Tax Free pilot retailers and obtain the required documents.','Validate at participating pilot departure locations; pilot geography expanded beyond its original rollout.','Refund under pilot/operator rules.','The currently published pilot is scheduled through 2026-12-31 unless extended/replaced.','Kazakhstan: Tax Free is still a pilot in 2026 rather than a fully mature nationwide scheme. Non-EAEU visitors can use participating retailers and designated departure locations, but thresholds, locations and operator details should be refreshed before each trip. Current government material says the pilot runs through 31 December 2026.','Official Kazakhstan government pilot material; some practical fields secondary','https://www.gov.kz/memleket/entities/kgd/documents/details/1026657?lang=en','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show ''Pilot'' rather than normal ''Available''; always refresh before trip.','Pilot / limited rollout','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('KE','KEN','Kenya','NO_SCHEME_CONFIRMED',NULL,NULL,NULL,'No dedicated nationwide tourist VAT-refund scheme confirmed.',NULL,NULL,NULL,'Do not buy on the assumption that ordinary retail tax will be refunded at departure.','No standard nationwide tourist retail tax-refund departure procedure is confirmed.',NULL,NULL,'Kenya: No dedicated nationwide tourist VAT-refund scheme confirmed. Ordinary shopping taxes, where applicable, should generally be treated as part of the purchase price. Duty-free airport/port shopping and business/diplomatic refund rules are separate. Recheck local rules before a high-value purchase because local programs can change.','Current official/secondary check','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show ''No standard tourist refund confirmed'' with update date.','No standard tourist refund confirmed','tripto.to-tax-refund-v1.0',90,'YES');
