INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('KR','KOR','Korea, Republic of','AVAILABLE','VAT','10%','KRW 15,000 per qualifying purchase','Eligible foreign visitors, generally staying in Korea for less than 6 months and meeting tax-refund conditions.','New, unopened/unused qualifying goods from certified tax-refund stores.','Used/consumed goods and non-qualifying services/items.','Goods generally must leave Korea within 3 months of purchase.','Shop at certified tax-refund stores; immediate refund may be available in some stores, otherwise obtain refund documentation.','For airport/port refund, keep goods, receipts and passport available and follow customs/refund kiosk procedures.','Immediate or departure refund depending on retailer/operator; operator rules may affect net payout.',NULL,'South Korea: VAT refunds are available at certified tax-refund stores. A qualifying purchase generally starts at KRW 15,000. Goods should remain new/unused and must normally leave Korea within 3 months. Some stores can issue an immediate refund; otherwise complete the airport/port refund procedure and keep passport, receipts and goods available.','Official Korea Tourism Organization','https://english.visitkorea.or.kr/svc/contents/infoBscView.do?vcontsId=140736',NULL,'2026-09-27','HIGH','NO','Show available + KRW 15,000 + immediate/departure options.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('KW','KWT','Kuwait','NO_GENERAL_VAT_GST','No broad VAT/GST (other duties/taxes may apply)',NULL,NULL,'No VAT currently implemented.',NULL,NULL,NULL,'There is generally no VAT/GST departure refund to request. Check item-specific duties/excise and local retail taxes.','No standard VAT/GST refund process.',NULL,NULL,'Kuwait: No VAT currently implemented. Because there is no broad VAT/GST of the usual kind to reclaim, there is generally no tourist departure VAT refund process. This does not mean every purchase is tax-free: customs duty, excise, local levies or sector taxes may still be built into the price.','Current tax-structure cross-check; territory-specific review recommended','https://vatinfo.org/countries-with-no-vat','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM','YES','Show ''No VAT/GST refund to claim''; avoid saying ''tax-free country''.','No broad VAT/GST refund to claim','tripto.to-tax-refund-v1.0',90,'YES');
