INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('LB','LBN','Lebanon','AVAILABLE_LIMITED','VAT','11% standard historically; verify current rate amid fiscal changes','Published legal materials contain an old nominal LBP threshold; do not display it without current confirmation','Eligible tourists/nonresidents buying qualifying goods from registered merchants.','New/unused qualifying goods exported in personal luggage.','Services, food/beverages, fuel, tobacco and other excluded categories under published rules.','Published rules require export within 3 months.','Obtain valid VAT invoice/refund documentation from a registered merchant.','Present goods and documents to Customs/refund operator at departure.','Operator/processing rules apply.',NULL,'Lebanon: a tourist VAT-refund framework exists for qualifying new/unused goods, with export generally required within 3 months. However, published minimum-purchase figures in Lebanese pounds are outdated by inflation/currency changes. tripto.to should show the scheme as available but must fetch/confirm the current practical threshold and operator procedure before giving a number.','Official legal framework; practical monetary threshold needs current confirmation','https://www.finance.gov.lb/en-us/Taxation/Pages/VAT.aspx','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM','YES','Never show legacy LBP threshold without fresh verification.','Available with important limitations','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('LS','LSO','Lesotho','NO_SCHEME_CONFIRMED',NULL,NULL,NULL,'No dedicated nationwide tourist VAT-refund scheme confirmed.',NULL,NULL,NULL,'Do not buy on the assumption that ordinary retail tax will be refunded at departure.','No standard nationwide tourist retail tax-refund departure procedure is confirmed.',NULL,NULL,'Lesotho: No dedicated nationwide tourist VAT-refund scheme confirmed. Ordinary shopping taxes, where applicable, should generally be treated as part of the purchase price. Duty-free airport/port shopping and business/diplomatic refund rules are separate. Recheck local rules before a high-value purchase because local programs can change.','Current official/secondary check','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show ''No standard tourist refund confirmed'' with update date.','No standard tourist refund confirmed','tripto.to-tax-refund-v1.0',90,'YES');
