INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('LY','LBY','Libya','NO_GENERAL_VAT_GST','No broad VAT/GST (other duties/taxes may apply)',NULL,NULL,'No broad VAT system currently in force.',NULL,NULL,NULL,'There is generally no VAT/GST departure refund to request. Check item-specific duties/excise and local retail taxes.','No standard VAT/GST refund process.',NULL,NULL,'Libya: No broad VAT system currently in force. Because there is no broad VAT/GST of the usual kind to reclaim, there is generally no tourist departure VAT refund process. This does not mean every purchase is tax-free: customs duty, excise, local levies or sector taxes may still be built into the price.','Current tax-structure cross-check; territory-specific review recommended','https://vatinfo.org/countries-with-no-vat','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM','YES','Show ''No VAT/GST refund to claim''; avoid saying ''tax-free country''.','No broad VAT/GST refund to claim','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('LI','LIE','Liechtenstein','AVAILABLE','VAT aligned with Swiss system','8.1% standard','CHF 300 including VAT per transaction under Swiss/Liechtenstein VAT tourist-export framework','Foreign-domiciled tourists under the Swiss VAT tourist-export framework used in the customs/VAT area.','Qualifying retail goods exported from the Swiss/Liechtenstein VAT area.','Purchases below threshold and goods not satisfying export rules.','Follow Swiss/Liechtenstein export validation rules.','Request tax-free/export documentation and keep ID/receipt.','Obtain the required customs/export confirmation when leaving the Swiss/Liechtenstein customs area.','Retailer/operator pays the refund after valid export proof.',NULL,'Liechtenstein: tourist tax-free shopping follows the Swiss VAT/customs framework. For ordinary tourist retail export, use the Swiss CHF 300 minimum and obtain the required export confirmation when leaving the Swiss/Liechtenstein customs area. Keep goods, receipt and identity documents available.','Swiss official consular/tax guidance applicable to the customs/VAT area','https://www.bundesreisezentrale.admin.ch/countries/liechtenstein/en/home/services/attestations-certificates/tax-free.html','https://www.estv.admin.ch/en/tax-free-for-tourists','2026-09-27','MEDIUM-HIGH','YES','Show available; note Swiss-system linkage.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('LT','LTU','Lithuania','AVAILABLE','VAT','21%','€55 for standard-rate goods','Habitual residence outside the EU; proof of residence/identity required. Retailer participation and local rules apply.','Qualifying goods for personal/non-commercial use that leave the EU in the traveler''s baggage.','Services and goods not exported; commercial quantities and other locally excluded categories.','Normally within 3 months of purchase; obtain customs/export validation at the final EU exit point.','Ask for the country''s tax-free/VAT-refund document and present passport or other accepted proof of non-EU residence.','Present goods, receipts and refund documents for customs/electronic validation at the final EU departure point; follow checked-baggage rules.','Retailer or authorized intermediary refunds the VAT; fees/commissions may reduce the amount received.',NULL,'Lithuania: tourist VAT refund is available for eligible travelers whose habitual residence is outside the EU. Standard VAT rate: 21%. Typical minimum purchase requirement: €55 for standard-rate goods (reduced-rate goods can differ). Buy from a retailer that supports tax-free sales, show proof of non-EU residence, keep the goods, receipt and tax-free document, and obtain customs/export validation when you leave the EU. The goods must normally leave the EU within 3 months of purchase. Services and goods consumed before export generally do not qualify. Refund operators may deduct fees.','Official EU framework; country threshold/rate cross-checked where available','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show ''Tax refund available''; keep threshold/source date visible.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('LU','LUX','Luxembourg','AVAILABLE','VAT','17%','€74','Habitual residence outside the EU; proof of residence/identity required. Retailer participation and local rules apply.','Qualifying goods for personal/non-commercial use that leave the EU in the traveler''s baggage.','Services and goods not exported; commercial quantities and other locally excluded categories.','Normally within 3 months of purchase; obtain customs/export validation at the final EU exit point.','Ask for the country''s tax-free/VAT-refund document and present passport or other accepted proof of non-EU residence.','Present goods, receipts and refund documents for customs/electronic validation at the final EU departure point; follow checked-baggage rules.','Retailer or authorized intermediary refunds the VAT; fees/commissions may reduce the amount received.',NULL,'Luxembourg: tourist VAT refund is available for eligible travelers whose habitual residence is outside the EU. Standard VAT rate: 17%. Typical minimum purchase requirement: €74 (per qualifying purchase). Buy from a retailer that supports tax-free sales, show proof of non-EU residence, keep the goods, receipt and tax-free document, and obtain customs/export validation when you leave the EU. The goods must normally leave the EU within 3 months of purchase. Services and goods consumed before export generally do not qualify. Refund operators may deduct fees.','Official EU framework; country threshold/rate cross-checked where available','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show ''Tax refund available''; keep threshold/source date visible.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
