INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('MY','MYS','Malaysia','NO_SCHEME_CONFIRMED',NULL,NULL,NULL,'Malaysia''s former tourist GST-refund scheme ended after GST was abolished in 2018; no ordinary tourist retail refund scheme is currently confirmed.',NULL,NULL,NULL,'Do not buy on the assumption that ordinary retail tax will be refunded at departure.','No standard nationwide tourist retail tax-refund departure procedure is confirmed.',NULL,NULL,'Malaysia: Malaysia''s former tourist GST-refund scheme ended after GST was abolished in 2018; no ordinary tourist retail refund scheme is currently confirmed. Ordinary shopping taxes, where applicable, should generally be treated as part of the purchase price. Duty-free airport/port shopping and business/diplomatic refund rules are separate. Recheck local rules before a high-value purchase because local programs can change.','Current official/secondary check','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show ''No standard tourist refund confirmed'' with update date.','No standard tourist refund confirmed','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('MV','MDV','Maldives','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Maldives: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
