INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('MQ','MTQ','Martinique','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'Outside the EU VAT area despite association with France; local indirect-tax rules differ.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Martinique: Outside the EU VAT area despite association with France; local indirect-tax rules differ. A reliable ordinary tourist retail refund workflow was not confirmed for this dataset. tripto.to should not inherit the parent country''s tax-free rules automatically; it should show ''Check local rules'' until a local tax/customs source is verified.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/how-does-vat-work/territorial-scope_en','2026-09-27','LOW','YES','Territory-specific rule required; never auto-copy parent country.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('MR','MRT','Mauritania','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Mauritania: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('MU','MUS','Mauritius','AVAILABLE','VAT','15%','Scheme/operator minimum varies; confirm at Tax Free/VAT-free shop','Eligible visitors purchasing goods under Mauritius duty/VAT refund or VAT-free supply arrangements.','Qualifying goods purchased with the required DF5/VAT invoice and exported.','Non-qualifying items/services.','Claim/verification at departure.','Obtain DF5/VAT invoice and retain passport/travel documentation.','Present goods, DF5/VAT invoice, passport and ticket at the MCCI refund counter/departure procedure.','Refund/VAT-free method depends on the participating merchant arrangement.',NULL,'Mauritius: visitors can obtain duty/VAT relief on qualifying purchases through participating arrangements. Keep the DF5/VAT invoice, passport, ticket and the goods, and present them at the MCCI/departure refund process. Because Mauritius supports more than one tax-free purchase model, the app should explain whether the shop sold the item VAT-free or expects a refund at departure.','Official Mauritius Revenue Authority','https://www.mra.mu/index.php/13-customs/154-refund-of-vat-on-purchases-made',NULL,'2026-09-27','HIGH','YES','Show available; distinguish VAT-free sale vs departure refund.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('YT','MYT','Mayotte','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'Outside the EU VAT area despite association with France; local indirect-tax rules differ.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Mayotte: Outside the EU VAT area despite association with France; local indirect-tax rules differ. A reliable ordinary tourist retail refund workflow was not confirmed for this dataset. tripto.to should not inherit the parent country''s tax-free rules automatically; it should show ''Check local rules'' until a local tax/customs source is verified.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/how-does-vat-work/territorial-scope_en','2026-09-27','LOW','YES','Territory-specific rule required; never auto-copy parent country.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('MX','MEX','Mexico','AVAILABLE_LIMITED','VAT (IVA)','16%','Common authorized-operator rule: MXN 1,200 per establishment; verify current operator','Eligible foreign tourists departing by air or sea, using participating/authorized refund retailers/operators.','Qualifying physical merchandise exported by the tourist.','Services and non-qualifying items.','Claim at eligible air/sea departure process.','Use participating retailer and obtain invoice/refund documentation in the correct traveler name/details.','Present passport/travel proof, invoices and goods to the authorized refund operator/departure process.','Authorized private operators charge service/processing fees.',NULL,'Mexico: tourist VAT refunds exist but are more operator/participating-store dependent than in many European systems. A common current minimum is MXN 1,200 per establishment for qualifying merchandise, with departure by air or sea. Because operator coverage matters, tripto.to should confirm the store and departure point before showing the refund as guaranteed.','Current operator/secondary guidance; official operational detail should be refreshed','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show ''Available at participating merchants/operators''.','Available with important limitations','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('FM','FSM','Micronesia, Federated States of','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Micronesia, Federated States of: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('MD','MDA','Moldova, Republic of','NO_SCHEME_CONFIRMED',NULL,NULL,NULL,'Official refund procedures found are for diplomatic/institutional cases, not ordinary tourists; no tourist retail scheme confirmed.',NULL,NULL,NULL,'Do not buy on the assumption that ordinary retail tax will be refunded at departure.','No standard nationwide tourist retail tax-refund departure procedure is confirmed.',NULL,NULL,'Moldova, Republic of: Official refund procedures found are for diplomatic/institutional cases, not ordinary tourists; no tourist retail scheme confirmed. Ordinary shopping taxes, where applicable, should generally be treated as part of the purchase price. Duty-free airport/port shopping and business/diplomatic refund rules are separate. Recheck local rules before a high-value purchase because local programs can change.','Current official/secondary check','https://mfa.gov.md/en/content/vat-refund-procedure-diplomatic-missions-consular-offices-and-international-organizations',NULL,'2026-09-27','MEDIUM','YES','Show ''No standard tourist refund confirmed'' with update date.','No standard tourist refund confirmed','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('MC','MCO','Monaco','AVAILABLE','VAT treated as France for VAT/customs purposes','20% standard French VAT','Use France tourist VAT-refund threshold/rules; participating retailer required','For VAT/customs purposes Monaco is treated as French territory; eligible non-EU-resident tourist rules apply.','Qualifying goods under the France/EU tourist-export framework.','Services/non-exported goods and normal France/EU exclusions.','Goods must leave EU VAT territory within the applicable 3-month framework.','Ask the Monaco retailer for the appropriate French/Tax Free export documentation.','Obtain export validation at the final EU exit point.','Retailer/operator fees may reduce refund.',NULL,'Monaco: for VAT and customs purposes Monaco is treated as France. Eligible travelers resident outside the EU can therefore use the France/EU tourist VAT-refund framework at participating retailers, with export validation at the final EU exit point. Do not treat Monaco as a separate no-VAT destination.','Official European Commission territorial-scope guidance','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/how-does-vat-work/territorial-scope_en','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','2026-09-27','HIGH','NO','Reuse France/EU framework with Monaco label.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('MN','MNG','Mongolia','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Mongolia: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('ME','MNE','Montenegro','AVAILABLE','VAT','21%','Official customs guidance states a €100 threshold; wording in older English guidance should be rechecked against the current 2026 law','Natural persons without permanent or temporary residence in Montenegro.','Qualifying goods purchased in Montenegro and taken out of the country.','Mineral oils, alcoholic beverages and tobacco products under the published guidance.','Goods must be taken out within 3 months of purchase.','Seller issues the PDV-PP VAT-refund form (or equivalent) with invoice.','Present the goods, PDV-PP form and invoice to Customs for inspection and certification when leaving Montenegro.','Refund is handled after the certified export documentation is returned under the retailer/operator procedure.',NULL,'Montenegro: nonresident travelers can claim VAT back on qualifying goods. The seller must issue the PDV-PP refund form and invoice, and the goods must be exported within 3 months. Customs validates the goods and documents at departure. The published English customs guidance references a €100 threshold, but tripto.to should re-check the exact threshold wording against the current 2026 VAT law before locking it in UI copy.','Official Montenegro Customs guidance + current 2026 VAT law publication','https://www.gov.me/en/documents/a7c33b8f-aa74-4197-b1fa-317ea466161f','https://wapi.gov.me/download/8f3b03d3-8fdb-40ea-92eb-b8514147c5ad?version=1.0','2026-09-27','MEDIUM-HIGH','YES','Show available; threshold marked ''verify current wording''.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('MS','MSR','Montserrat','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Montserrat: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('MA','MAR','Morocco','AVAILABLE','VAT','20%','MAD 2,000 including VAT at the same store/day under current tourist-refund guidance','Eligible nonresident tourists under Morocco''s tourist VAT-refund rules.','Qualifying goods exported in personal luggage.','Food, tobacco, medicines, precious stones/metals, weapons, vehicles and other excluded categories under the scheme.','Goods generally must be exported within 3 months; refund submission deadlines also apply.','Request tourist VAT-refund documents/invoice from a participating retailer.','Present goods and documents for Customs validation at an eligible departure point.','Refund operator/bank may deduct processing fees.',NULL,'Morocco: eligible nonresident tourists can claim VAT back on qualifying exported goods. Current guidance uses a MAD 2,000 minimum including VAT at the same store/day. Keep the goods and refund documents and obtain Customs validation when leaving. Food, tobacco, medicines, precious stones/metals, weapons and vehicles are among the excluded categories.','Current country/secondary guidance; recheck official tax administration before production lock','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM-HIGH','YES','Show available; official source refresh recommended.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
