INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('NA','NAM','Namibia','AVAILABLE','VAT','15%','More than N$250 tax-inclusive','Individuals who do not hold a Namibian passport / qualifying nonresidents exporting the goods.','Goods bought in Namibia and removed as the traveler''s personal accompanied baggage.','Claims without required invoices/export proof; other legal exclusions may apply.','Claim requires documentary proof of export; nonresident refund claims are processed under VAT Act rules.','Keep original tax invoices (or legally acceptable equivalents).','Obtain documentary proof of export and submit the required refund claim/documentation.','Refund procedure is authorized under Namibia''s VAT Act; practical operator/payment method should be confirmed at departure.',NULL,'Namibia: the VAT Act allows a refund to qualifying foreign visitors on goods bought in Namibia and exported as accompanied baggage. The purchase value must exceed N$250 tax-inclusive. Keep original tax invoices and obtain proof of export. The legal right is clear, but tripto.to should still re-check the current practical claim desk/operator process before showing detailed airport instructions.','Official/legal government trade portal and VAT Act','https://namibiatradeportal.gov.na/trade-goods/measure-details/view_express_entity/1850','https://www.namra.org.na/documents/cms/uploaded/value-added-tax-act-10-of-2000-8d9c425ffc.pdf','2026-09-27','HIGH','YES','Show available + N$250; practical departure instructions marked ''check current desk''.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
