INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('NP','NPL','Nepal','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Nepal: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('NL','NLD','Netherlands','AVAILABLE','VAT','21%','€50','Habitual residence outside the EU; proof of residence/identity required. Retailer participation and local rules apply.','Qualifying goods for personal/non-commercial use that leave the EU in the traveler''s baggage.','Services and goods not exported; commercial quantities and other locally excluded categories.','Normally within 3 months of purchase; obtain customs/export validation at the final EU exit point.','Ask for the country''s tax-free/VAT-refund document and present passport or other accepted proof of non-EU residence.','Present goods, receipts and refund documents for customs/electronic validation at the final EU departure point; follow checked-baggage rules.','Retailer or authorized intermediary refunds the VAT; fees/commissions may reduce the amount received.',NULL,'Netherlands: tourist VAT refund is available for eligible travelers whose habitual residence is outside the EU. Standard VAT rate: 21%. Typical minimum purchase requirement: €50 (per qualifying purchase). Buy from a retailer that supports tax-free sales, show proof of non-EU residence, keep the goods, receipt and tax-free document, and obtain customs/export validation when you leave the EU. The goods must normally leave the EU within 3 months of purchase. Services and goods consumed before export generally do not qualify. Refund operators may deduct fees.','Official EU framework; country threshold/rate cross-checked where available','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show ''Tax refund available''; keep threshold/source date visible.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('NC','NCL','New Caledonia','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'New Caledonia has its own indirect-tax system; do not copy France/EU rules.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'New Caledonia: New Caledonia has its own indirect-tax system; do not copy France/EU rules. A reliable ordinary tourist retail refund workflow was not confirmed for this dataset. tripto.to should not inherit the parent country''s tax-free rules automatically; it should show ''Check local rules'' until a local tax/customs source is verified.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Territory-specific rule required; never auto-copy parent country.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('NZ','NZL','New Zealand','NO_SCHEME_CONFIRMED',NULL,NULL,NULL,'No ordinary nationwide tourist GST refund on retail shopping is confirmed.',NULL,NULL,NULL,'Do not buy on the assumption that ordinary retail tax will be refunded at departure.','No standard nationwide tourist retail tax-refund departure procedure is confirmed.',NULL,NULL,'New Zealand: No ordinary nationwide tourist GST refund on retail shopping is confirmed. Ordinary shopping taxes, where applicable, should generally be treated as part of the purchase price. Duty-free airport/port shopping and business/diplomatic refund rules are separate. Recheck local rules before a high-value purchase because local programs can change.','Current official/secondary check','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show ''No standard tourist refund confirmed'' with update date.','No standard tourist refund confirmed','tripto.to-tax-refund-v1.0',90,'YES');
