INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('NO','NOR','Norway','AVAILABLE','VAT','25%','More than NOK 315 at an affiliated/participating store','Current airport guidance: traveler living outside Norway, Sweden, Denmark and Finland; operator conditions apply.','Eligible goods bought from participating tax-free retailers and exported by the traveler.','Non-qualifying/consumed goods and purchases outside operator scheme.','Current Avinor guidance requires export within 30 days.','Ask for Tax Free documentation at an affiliated store and keep passport/ID and receipts.','Present goods, Tax Free documentation, ID/passport and ticket for validation before checked baggage is handed over where required.','Refund commonly to card through participating operators; operator fee reduces payout.',NULL,'Norway: tax-free shopping refunds are available through participating retailers/operators. Current airport guidance uses a purchase threshold above NOK 315 and requires export within 30 days. Keep the goods, Tax Free form, passport/ID and ticket, and complete validation before checking baggage when the goods are in hold luggage.','Official Avinor airport guidance','https://www.avinor.no/en/practical-info/Tax-refund/','https://taxfree.weareplanet.com/countries','2026-09-27','HIGH','NO','Show available + NOK 315 + 30 days.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('OM','OMN','Oman','LEGAL_FRAMEWORK_VERIFY_OPERATIONAL','VAT','5%','Not confirmed for a live tourist retail workflow','Oman''s VAT law provides for tourist refund on eligible personal-luggage goods under prescribed conditions.','Eligible goods for personal use carried out of Oman/GCC under the legal framework.','Operational exclusions depend on implementing procedures.','Depends on implementing procedure.','Do not promise a refund unless the retailer confirms participation in a currently operating official scheme.','A fully operational nationwide tourist refund process was not confirmed in this research pass.','Not confirmed.',NULL,'Oman: the VAT law contains a tourist-refund mechanism for eligible goods carried out by visitors, but I did not confirm a fully operational nationwide retail/airport workflow for September 2026. tripto.to should display ''Legal framework exists — confirm current operation'' and should not tell a traveler to expect a refund until an official operator/store/departure process is verified.','Official legal framework; operational status not confirmed','https://taxoman.gov.om/','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM','YES','Do not show as guaranteed available.','Legal framework exists; operation not confirmed','tripto.to-tax-refund-v1.0',90,'YES');
