INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('PE','PER','Peru','AVAILABLE','IGV (VAT)','18%','S/100 minimum per qualifying good/invoice under current Tax Free rules','Foreign nonresident tourists within the permitted stay period, buying from authorized Tax Free stores.','Qualifying goods bought from authorized stores and carried out of Peru by air/sea.','Services and purchases outside the authorized Tax Free process.','Claim at departure while eligible as a tourist; current process is tied to authorized departure workflow.','Use an authorized Tax Free store, obtain the Tax Free invoice, and pay with an international card in the tourist''s name where required.','Use the Tax Free kiosk/app workflow at Jorge Chávez International Airport and comply with inspection/validation instructions.','Refund is sent to the qualifying payment card, normally within 5 calendar days, less the authorized collaborator''s commission.',NULL,'Peru: the Tax Free system is operational for qualifying foreign tourists shopping at authorized stores. Current rules use a S/100 minimum for qualifying purchases, require the Tax Free invoice and eligible payment method, and route the departure claim through the airport/app process. The refund goes back to the card after validation, less the operator commission.','Official SUNAT','https://emprender.sunat.gob.pe/principales-impuestos/imp-general-las-ventas-igv/tax-free',NULL,'2026-09-27','HIGH','NO','Show available + authorized-store/airport workflow.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('PH','PHL','Philippines','ROLLOUT','VAT','12%','PHP 3,000 under the enacted tourist VAT-refund framework','Foreign passport holders meeting the tourist eligibility rules.','Eligible tangible goods purchased from accredited/participating stores and exported.','Services and other excluded categories.','Goods must be taken out within 60 days under the legal framework.','Use an accredited/participating retailer once operational and obtain the required electronic/refund documentation.','Operational airport/provider coverage must be confirmed before relying on a refund.','Depends on the accredited operator once fully operational.','The legal framework is enacted, but 2026 government materials still show operator/accreditation rollout work.','Philippines: the tourist VAT-refund law is in place, using a PHP 3,000 purchase threshold and a 60-day export rule for eligible tangible goods. However, 2026 government material still reflects operator/accreditation rollout. tripto.to should not present this as universally available at every airport/store until the participating retailer and departure-point process are confirmed.','Official Department of Finance / rollout material','https://www.dof.gov.ph/','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show ''Rolling out — confirm availability'' rather than guaranteed refund.','Legal scheme rolling out','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('PN','PCN','Pitcairn','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Pitcairn: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('PL','POL','Poland','AVAILABLE','VAT','23%','PLN 200','Habitual residence outside the EU; proof of residence/identity required. Retailer participation and local rules apply.','Qualifying goods for personal/non-commercial use that leave the EU in the traveler''s baggage.','Services and goods not exported; commercial quantities and other locally excluded categories.','Normally within 3 months of purchase; obtain customs/export validation at the final EU exit point.','Ask for the country''s tax-free/VAT-refund document and present passport or other accepted proof of non-EU residence.','Present goods, receipts and refund documents for customs/electronic validation at the final EU departure point; follow checked-baggage rules.','Retailer or authorized intermediary refunds the VAT; fees/commissions may reduce the amount received.',NULL,'Poland: tourist VAT refund is available for eligible travelers whose habitual residence is outside the EU. Standard VAT rate: 23%. Typical minimum purchase requirement: PLN 200 (per qualifying purchase). Buy from a retailer that supports tax-free sales, show proof of non-EU residence, keep the goods, receipt and tax-free document, and obtain customs/export validation when you leave the EU. The goods must normally leave the EU within 3 months of purchase. Services and goods consumed before export generally do not qualify. Refund operators may deduct fees.','Official EU framework; country threshold/rate cross-checked where available','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show ''Tax refund available''; keep threshold/source date visible.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('PT','PRT','Portugal','AVAILABLE','VAT','23%','€50 excluding VAT','Habitual residence outside the EU; proof of residence/identity required. Retailer participation and local rules apply.','Qualifying goods for personal/non-commercial use that leave the EU in the traveler''s baggage.','Services and goods not exported; commercial quantities and other locally excluded categories.','Normally within 3 months of purchase; obtain customs/export validation at the final EU exit point.','Ask for the country''s tax-free/VAT-refund document and present passport or other accepted proof of non-EU residence.','Present goods, receipts and refund documents for customs/electronic validation at the final EU departure point; follow checked-baggage rules.','Retailer or authorized intermediary refunds the VAT; fees/commissions may reduce the amount received.',NULL,'Portugal: tourist VAT refund is available for eligible travelers whose habitual residence is outside the EU. Standard VAT rate: 23%. Typical minimum purchase requirement: €50 excluding VAT (per invoice; purchase must exceed €50 net of VAT). Buy from a retailer that supports tax-free sales, show proof of non-EU residence, keep the goods, receipt and tax-free document, and obtain customs/export validation when you leave the EU. The goods must normally leave the EU within 3 months of purchase. Services and goods consumed before export generally do not qualify. Refund operators may deduct fees. Portugal uses the e-Taxfree electronic certification system.','Official EU framework; country threshold/rate cross-checked where available','https://info.portaldasfinancas.gov.pt/en/tax-information/travellers-and-customs/e-taxfree-vat-refund-for-tourists/Pages/default.aspx','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','2026-09-27','HIGH','NO','Show ''Tax refund available''; keep threshold/source date visible.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('PR','PRI','Puerto Rico','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'Puerto Rico uses local sales/use tax; there is no U.S.-wide tourist VAT system to inherit.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Puerto Rico: Puerto Rico uses local sales/use tax; there is no U.S.-wide tourist VAT system to inherit. A reliable ordinary tourist retail refund workflow was not confirmed for this dataset. tripto.to should not inherit the parent country''s tax-free rules automatically; it should show ''Check local rules'' until a local tax/customs source is verified.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Territory-specific rule required; never auto-copy parent country.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('QA','QAT','Qatar','NO_GENERAL_VAT_GST','No broad VAT/GST (other duties/taxes may apply)',NULL,NULL,'No VAT currently implemented as of the verification date.',NULL,NULL,NULL,'There is generally no VAT/GST departure refund to request. Check item-specific duties/excise and local retail taxes.','No standard VAT/GST refund process.',NULL,NULL,'Qatar: No VAT currently implemented as of the verification date. Because there is no broad VAT/GST of the usual kind to reclaim, there is generally no tourist departure VAT refund process. This does not mean every purchase is tax-free: customs duty, excise, local levies or sector taxes may still be built into the price.','Current tax-structure cross-check; territory-specific review recommended','https://vatinfo.org/countries-with-no-vat','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM','YES','Show ''No VAT/GST refund to claim''; avoid saying ''tax-free country''.','No broad VAT/GST refund to claim','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('RO','ROU','Romania','AVAILABLE','VAT','21%','RON 250','Habitual residence outside the EU; proof of residence/identity required. Retailer participation and local rules apply.','Qualifying goods for personal/non-commercial use that leave the EU in the traveler''s baggage.','Services and goods not exported; commercial quantities and other locally excluded categories.','Normally within 3 months of purchase; obtain customs/export validation at the final EU exit point.','Ask for the country''s tax-free/VAT-refund document and present passport or other accepted proof of non-EU residence.','Present goods, receipts and refund documents for customs/electronic validation at the final EU departure point; follow checked-baggage rules.','Retailer or authorized intermediary refunds the VAT; fees/commissions may reduce the amount received.',NULL,'Romania: tourist VAT refund is available for eligible travelers whose habitual residence is outside the EU. Standard VAT rate: 21%. Typical minimum purchase requirement: RON 250 (per qualifying purchase). Buy from a retailer that supports tax-free sales, show proof of non-EU residence, keep the goods, receipt and tax-free document, and obtain customs/export validation when you leave the EU. The goods must normally leave the EU within 3 months of purchase. Services and goods consumed before export generally do not qualify. Refund operators may deduct fees.','Official EU framework; country threshold/rate cross-checked where available','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show ''Tax refund available''; keep threshold/source date visible.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('RU','RUS','Russian Federation','AVAILABLE_LIMITED','VAT','20% standard','Current statutory/operator threshold applies; refresh before trip','Eligible non-EAEU foreign visitors under Russia''s Tax Free framework, subject to participating merchants and current payment/operator restrictions.','Qualifying goods from designated Tax Free retailers exported through designated checkpoints.','Scheme exclusions apply.','Follow current Tax Free/customs export window.','Use a participating Tax Free retailer and obtain required documents.','Use a designated checkpoint; practical operator/card availability can be affected by payment-system restrictions.','Provider fees and payment-method restrictions can materially affect the claim.',NULL,'Russia: a legal Tax Free scheme exists for eligible non-EAEU visitors using participating retailers and designated exit points. In 2026, practical refund methods can be affected by payment-system and operator restrictions, so tripto.to should confirm the exact store, departure point and refund method before showing a claim as usable.','Legal/secondary current check; operational payment availability can change','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show ''Limited/verify operator and payment method''.','Available with important limitations','tripto.to-tax-refund-v1.0',90,'YES');
