INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SA','SAU','Saudi Arabia','AVAILABLE_LIMITED','VAT','15%','Current participating-retailer/provider threshold should be checked at purchase','Eligible international tourists purchasing eligible goods from participating retailers under the new tourist-refund mechanism.','Eligible goods carried by the tourist on departure; vehicles/tobacco and other exclusions apply under the implementing framework.','Excluded goods under Article 73/provider rules; goods not exported with the traveler.','Follow current provider/ZATCA tourist-refund departure rules.','Use a participating retailer and make sure the purchase is registered for tourist VAT refund.','As of September 2026, a Global Blue/Alinma refund service is operating at King Khalid International Airport in Riyadh, with progressive expansion planned.','Provider methods/fees apply; current rollout details should be confirmed before departure.','New service launched in Riyadh in September 2026 and is intended to expand to additional locations.','Saudi Arabia: a tourist VAT-refund service has now begun operating, but coverage is still expanding. In September 2026 Alinma and Global Blue launched the service for eligible international tourists at King Khalid International Airport in Riyadh, with more locations planned. tripto.to should show this as ''limited rollout'' and confirm the user''s departure airport before promising a refund.','Current provider/bank launch + ZATCA legal framework','https://www.alinma.com/en/About-the-Bank/The-Bank/News/2026/9/Alinma-and-Global-Blue','https://www.zatca.gov.sa/en/Pages/default.aspx','2026-09-27','HIGH','YES','Show ''Limited rollout'' and require departure-airport check.','Available with important limitations','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SN','SEN','Senegal','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Senegal: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('RS','SRB','Serbia','AVAILABLE','VAT','20%','RSD 6,000 including VAT; can be one or multiple invoices from the same seller within the permitted period','Traveler with neither permanent nor temporary residence in Serbia, exporting goods for non-commercial purposes.','Goods bought in Serbia and exported in personal luggage for non-commercial use.','Goods not exported or commercial quantities.','Goods must be exported before the end of 3 calendar months following the month of sale; refund documentation can be submitted within 12 months of export.','Keep invoice/fiscal receipt and obtain the traveler''s VAT-refund request/document from the seller/operator.','Have Customs certify the VAT-refund request/evidence of export, then submit documentation to the seller/operator.','Seller/operator refunds VAT; a commission may be deducted depending on provider.',NULL,'Serbia: foreign travelers without Serbian residence can claim VAT back on qualifying goods. The minimum is RSD 6,000 including VAT, and qualifying invoices from the same seller can be combined under the rules. Export the goods within the legal time limit, get Customs certification, then submit the validated documents to the seller/operator.','Official Serbian Tax Administration','https://www.purs.gov.rs/en/Non-residents/Vat/vat-refund-to-the-foreign-passenger.html',NULL,'2026-09-27','HIGH','NO','Show available + RSD 6,000.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SC','SYC','Seychelles','AVAILABLE','VAT','15%','Refund amount must exceed SCR 150 (not simply purchase value)','Eligible departing visitors under Seychelles Revenue Commission tourist VAT-refund rules.','Qualifying goods in the listed eligible categories.','Services and non-qualifying categories.','Claim on departure with goods available for verification.','Keep valid tax invoices/receipts and travel documents.','Present goods for verification before check-in, then complete the refund after immigration as directed.','Refund can be paid in supported currencies including USD/EUR/GBP/SCR according to current procedure.',NULL,'Seychelles: tourist VAT refunds are available on qualifying goods, but the key threshold is that the refund amount itself must exceed SCR 150. Keep invoices, passport/ticket and the goods. Have the goods verified before check-in, then complete the refund after immigration.','Official Seychelles Revenue Commission','https://src.gov.sc/customs-and-excises/',NULL,'2026-09-27','HIGH','NO','Show available; clearly say threshold is refund amount, not purchase amount.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SL','SLE','Sierra Leone','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Sierra Leone: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SG','SGP','Singapore','AVAILABLE','GST','9%','SGD 100 including GST at the same retailer; up to 3 same-day receipts may be combined under scheme rules','Tourist generally age 16+, not a Singapore citizen/permanent resident or departing crew, meeting eTRS conditions.','Eligible goods bought from participating eTRS retailers and taken out of Singapore.','Services, accommodation and other excluded/consumed items; goods not exported.','Goods generally must be taken out within 2 months from purchase; departure validation timing rules apply.','Shop at participating eTRS retailers and present the passport/travel document used for the claim.','Use eTRS kiosks/airport procedures; checked-baggage goods must be handled before check-in where required, hand-carry goods after immigration as directed.','Refund can be paid by available electronic/cash methods; service fees are deducted.',NULL,'Singapore: the Electronic Tourist Refund Scheme (eTRS) refunds GST on qualifying purchases from participating retailers. Spend at least SGD 100 including GST at the same retailer; qualifying same-day receipts can be combined under the rules. Keep the goods and travel document, complete eTRS validation at departure, and note that fees reduce the final refund.','Official Singapore tax authority','https://www.iras.gov.sg/taxes/goods-services-tax-(gst)/consumers/tourist-refund-scheme',NULL,'2026-09-27','HIGH','NO','Show eTRS available + SGD 100.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SX','SXM','Sint Maarten (Dutch part)','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'Sint Maarten has its own turnover tax system; do not copy Netherlands/EU rules.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Sint Maarten (Dutch part): Sint Maarten has its own turnover tax system; do not copy Netherlands/EU rules. A reliable ordinary tourist retail refund workflow was not confirmed for this dataset. tripto.to should not inherit the parent country''s tax-free rules automatically; it should show ''Check local rules'' until a local tax/customs source is verified.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Territory-specific rule required; never auto-copy parent country.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SK','SVK','Slovakia','AVAILABLE','VAT','23%','€100','Habitual residence outside the EU; proof of residence/identity required. Retailer participation and local rules apply.','Qualifying goods for personal/non-commercial use that leave the EU in the traveler''s baggage.','Services and goods not exported; commercial quantities and other locally excluded categories.','Normally within 3 months of purchase; obtain customs/export validation at the final EU exit point.','Ask for the country''s tax-free/VAT-refund document and present passport or other accepted proof of non-EU residence.','Present goods, receipts and refund documents for customs/electronic validation at the final EU departure point; follow checked-baggage rules.','Retailer or authorized intermediary refunds the VAT; fees/commissions may reduce the amount received.',NULL,'Slovakia: tourist VAT refund is available for eligible travelers whose habitual residence is outside the EU. Standard VAT rate: 23%. Typical minimum purchase requirement: €100 (per qualifying purchase). Buy from a retailer that supports tax-free sales, show proof of non-EU residence, keep the goods, receipt and tax-free document, and obtain customs/export validation when you leave the EU. The goods must normally leave the EU within 3 months of purchase. Services and goods consumed before export generally do not qualify. Refund operators may deduct fees.','Official EU framework; country threshold/rate cross-checked where available','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show ''Tax refund available''; keep threshold/source date visible.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SI','SVN','Slovenia','AVAILABLE','VAT','22%','€50.01','Habitual residence outside the EU; proof of residence/identity required. Retailer participation and local rules apply.','Qualifying goods for personal/non-commercial use that leave the EU in the traveler''s baggage.','Services and goods not exported; commercial quantities and other locally excluded categories.','Normally within 3 months of purchase; obtain customs/export validation at the final EU exit point.','Ask for the country''s tax-free/VAT-refund document and present passport or other accepted proof of non-EU residence.','Present goods, receipts and refund documents for customs/electronic validation at the final EU departure point; follow checked-baggage rules.','Retailer or authorized intermediary refunds the VAT; fees/commissions may reduce the amount received.',NULL,'Slovenia: tourist VAT refund is available for eligible travelers whose habitual residence is outside the EU. Standard VAT rate: 22%. Typical minimum purchase requirement: €50.01 (per qualifying purchase). Buy from a retailer that supports tax-free sales, show proof of non-EU residence, keep the goods, receipt and tax-free document, and obtain customs/export validation when you leave the EU. The goods must normally leave the EU within 3 months of purchase. Services and goods consumed before export generally do not qualify. Refund operators may deduct fees.','Official EU framework; country threshold/rate cross-checked where available','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show ''Tax refund available''; keep threshold/source date visible.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SB','SLB','Solomon Islands','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Solomon Islands: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SO','SOM','Somalia','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Somalia: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('ZA','ZAF','South Africa','AVAILABLE','VAT','15%','Total qualifying purchases must exceed R250 per visit','Qualifying nonresident/foreign visitors exporting movable goods from South Africa.','Qualifying movable goods physically exported by the visitor.','Services and goods not exported; scheme exclusions apply.','Goods generally must be exported within 90 days from tax invoice date.','Obtain valid tax invoices and keep goods/documentation.','Present goods and documents to Customs/VAT Refund Administrator at the designated departure process, following checked-baggage rules.','Refund paid under the VAT Refund Administrator process; fees may apply.',NULL,'South Africa: qualifying foreign visitors can claim VAT back on movable goods exported from the country. Total qualifying purchases must exceed R250. Keep valid tax invoices and the goods, export them within 90 days, and complete Customs/VAT Refund Administrator validation at departure. Services do not qualify.','Official SARS / South African government','https://www.sars.gov.za/types-of-tax/value-added-tax/vat-refunds-for-tourists-and-foreign-enterprises/','https://www.gov.za/services/services-organisations/tax/vat/refund-vat-qualifying-purchasers','2026-09-27','HIGH','NO','Show available + R250 + 90 days.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('GS','SGS','South Georgia and the South Sandwich Islands','NOT_APPLICABLE','Not applicable / no ordinary retail tourist system',NULL,NULL,'South Georgia and the South Sandwich Islands have no ordinary retail tourist tax-refund system comparable to normal destinations.',NULL,NULL,NULL,'No standard tourist shopping refund flow.','No standard refund flow.',NULL,NULL,'South Georgia and the South Sandwich Islands: South Georgia and the South Sandwich Islands have no ordinary retail tourist tax-refund system comparable to normal destinations. A normal VAT/GST tourist-refund workflow is therefore not applicable. Any purchases made through expedition, base, ship or concession operators follow their own pricing/tax arrangements.','Jurisdiction characteristics; not a consumer tax-refund destination','https://www.iso.org/iso-3166-country-codes.html',NULL,'2026-09-27','HIGH','NO','Show ''Not applicable'' rather than ''No''.','Not applicable','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SS','SSD','South Sudan','NO_SCHEME_CONFIRMED',NULL,NULL,NULL,'No dedicated nationwide tourist VAT-refund scheme confirmed.',NULL,NULL,NULL,'Do not buy on the assumption that ordinary retail tax will be refunded at departure.','No standard nationwide tourist retail tax-refund departure procedure is confirmed.',NULL,NULL,'South Sudan: No dedicated nationwide tourist VAT-refund scheme confirmed. Ordinary shopping taxes, where applicable, should generally be treated as part of the purchase price. Duty-free airport/port shopping and business/diplomatic refund rules are separate. Recheck local rules before a high-value purchase because local programs can change.','Current official/secondary check','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show ''No standard tourist refund confirmed'' with update date.','No standard tourist refund confirmed','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('ES','ESP','Spain','AVAILABLE','VAT','21%','No statutory minimum for standard tourist-refund eligibility','Habitual residence outside the EU; proof of residence/identity required. Retailer participation and local rules apply.','Qualifying goods for personal/non-commercial use that leave the EU in the traveler''s baggage.','Services and goods not exported; commercial quantities and other locally excluded categories.','Normally within 3 months of purchase; obtain customs/export validation at the final EU exit point.','Ask for the country''s tax-free/VAT-refund document and present passport or other accepted proof of non-EU residence.','Present goods, receipts and refund documents for customs/electronic validation at the final EU departure point; follow checked-baggage rules.','Retailer or authorized intermediary refunds the VAT; fees/commissions may reduce the amount received.',NULL,'Spain: tourist VAT refund is available for eligible travelers whose habitual residence is outside the EU. Standard VAT rate: 21%. Typical minimum purchase requirement: No statutory minimum for standard tourist-refund eligibility (retailer participation still required). Buy from a retailer that supports tax-free sales, show proof of non-EU residence, keep the goods, receipt and tax-free document, and obtain customs/export validation when you leave the EU. The goods must normally leave the EU within 3 months of purchase. Services and goods consumed before export generally do not qualify. Refund operators may deduct fees.','Official EU framework; country threshold/rate cross-checked where available','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show ''Tax refund available''; keep threshold/source date visible.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('LK','LKA','Sri Lanka','AVAILABLE','VAT','18% standard','Confirm current TVRS purchase threshold at participating retailer','Non-citizen/nonresident tourist, generally age 18+, on tourist visa and staying less than 90 days under TVRS conditions.','Qualifying goods bought under the Tourist VAT Refund Scheme.','Non-qualifying goods/services.','Claim at departure within the eligible tourist stay.','Use participating TVRS retailer and obtain required VAT/tourist refund documentation.','Complete the TVRS departure process with passport, goods and documents.','Refund under Inland Revenue/TVRS procedure.',NULL,'Sri Lanka: the Tourist VAT Refund Scheme is available to qualifying nonresident tourists, generally age 18+ on a tourist visa and staying under 90 days. Shop through participating TVRS retailers, retain the required invoices/documents and goods, and complete the departure claim. The exact current minimum purchase threshold should be refreshed from Inland Revenue before hard-coding it.','Official Sri Lanka Inland Revenue','https://www.ird.gov.lk/en/type%20of%20taxes/sitepages/tourist%20vat%20refund%20scheme%20%28tvrs%29.aspx?menuid=1213',NULL,'2026-09-27','HIGH','YES','Show available; minimum must remain refreshable.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SD','SDN','Sudan','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Sudan: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SR','SUR','Suriname','NO_SCHEME_CONFIRMED',NULL,NULL,NULL,'No dedicated nationwide tourist VAT-refund scheme confirmed.',NULL,NULL,NULL,'Do not buy on the assumption that ordinary retail tax will be refunded at departure.','No standard nationwide tourist retail tax-refund departure procedure is confirmed.',NULL,NULL,'Suriname: No dedicated nationwide tourist VAT-refund scheme confirmed. Ordinary shopping taxes, where applicable, should generally be treated as part of the purchase price. Duty-free airport/port shopping and business/diplomatic refund rules are separate. Recheck local rules before a high-value purchase because local programs can change.','Current official/secondary check','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show ''No standard tourist refund confirmed'' with update date.','No standard tourist refund confirmed','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SJ','SJM','Svalbard and Jan Mayen','NO_GENERAL_VAT_GST','No broad VAT/GST (other duties/taxes may apply)',NULL,NULL,'Svalbard is outside Norwegian VAT; no ordinary tourist VAT refund is needed there. Jan Mayen has no normal tourist retail economy.',NULL,NULL,NULL,'There is generally no VAT/GST departure refund to request. Check item-specific duties/excise and local retail taxes.','No standard VAT/GST refund process.',NULL,NULL,'Svalbard and Jan Mayen: Svalbard is outside Norwegian VAT; no ordinary tourist VAT refund is needed there. Jan Mayen has no normal tourist retail economy. Because there is no broad VAT/GST of the usual kind to reclaim, there is generally no tourist departure VAT refund process. This does not mean every purchase is tax-free: customs duty, excise, local levies or sector taxes may still be built into the price.','Current tax-structure cross-check; territory-specific review recommended','https://vatinfo.org/countries-with-no-vat','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM','YES','Show ''No VAT/GST refund to claim''; avoid saying ''tax-free country''.','No broad VAT/GST refund to claim','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SE','SWE','Sweden','AVAILABLE','VAT','25%','SEK 200','Habitual residence outside the EU; proof of residence/identity required. Retailer participation and local rules apply.','Qualifying goods for personal/non-commercial use that leave the EU in the traveler''s baggage.','Services and goods not exported; commercial quantities and other locally excluded categories.','Normally within 3 months of purchase; obtain customs/export validation at the final EU exit point.','Ask for the country''s tax-free/VAT-refund document and present passport or other accepted proof of non-EU residence.','Present goods, receipts and refund documents for customs/electronic validation at the final EU departure point; follow checked-baggage rules.','Retailer or authorized intermediary refunds the VAT; fees/commissions may reduce the amount received.',NULL,'Sweden: tourist VAT refund is available for eligible travelers whose habitual residence is outside the EU. Standard VAT rate: 25%. Typical minimum purchase requirement: SEK 200 (per qualifying purchase). Buy from a retailer that supports tax-free sales, show proof of non-EU residence, keep the goods, receipt and tax-free document, and obtain customs/export validation when you leave the EU. The goods must normally leave the EU within 3 months of purchase. Services and goods consumed before export generally do not qualify. Refund operators may deduct fees.','Official EU framework; country threshold/rate cross-checked where available','https://taxation-customs.ec.europa.eu/taxation/vat/vat-directive/vat-refunds_en','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show ''Tax refund available''; keep threshold/source date visible.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('CH','CHE','Switzerland','AVAILABLE','VAT','8.1%','CHF 300 including VAT per sales transaction','Tourist/customer domiciled outside Switzerland under Swiss export-in-tourist-traffic rules.','Qualifying retail goods exported from Switzerland.','Purchases below CHF 300 and goods not meeting export/document rules.','Export and customs confirmation must meet Swiss tourist-export rules; confirm within border-office hours.','Ask the seller for the export/tax-free document and keep official ID and receipt.','Have the export document confirmed by Swiss Customs at a staffed crossing/within clearance hours; present goods when required.','The seller/operator handles the refund; Swiss tax/customs authorities do not themselves pay the retail refund to the traveler.',NULL,'Switzerland: tax-free shopping is available when the retail price is at least CHF 300 including VAT per transaction. The traveler must be domiciled abroad. Ask the seller for the export document, keep the goods and ID, and obtain customs confirmation when leaving Switzerland. The retailer/operator—not Swiss Customs—ultimately pays the refund.','Official Swiss Federal Tax Administration / Customs','https://www.estv.admin.ch/en/tax-free-for-tourists','https://www.bazg.admin.ch/en/refunds-of-swiss-vat-private','2026-09-27','HIGH','NO','Show available + CHF 300.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('SY','SYR','Syrian Arab Republic','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Syrian Arab Republic: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('TW','TWN','Taiwan, Province of China','AVAILABLE','VAT','5%','NT$2,000 on the same day at the same designated Tax Refund Shopping store','Eligible foreign travelers meeting Taiwan tourist tax-refund conditions.','Eligible goods from designated tax-refund stores that are taken out of Taiwan.','Consumed/non-exported goods and other excluded categories.','Goods must generally be exported within 90 days of purchase.','Shop at a designated Tax Refund Shopping store and present passport/required travel document.','Use the applicable in-store, airport/port or electronic refund procedure and keep goods/documents available for inspection.','Refund is based on eligible VAT less applicable processing/service fees.',NULL,'Taiwan: foreign travelers can claim a VAT refund on qualifying purchases from designated tax-refund shops. Spend at least NT$2,000 on the same day at the same store, keep the goods and documents, and export the goods within 90 days. Follow the store or departure-point refund procedure.','Official Taiwan tourism/tax guidance','https://eng.taiwan.net.tw/m1.aspx?sNo=0024567',NULL,'2026-09-27','HIGH','NO','Show available + NT$2,000 + 90 days.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
