INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('TH','THA','Thailand','AVAILABLE','VAT','7%','THB 2,000 including VAT per participating supplier/store per day','Eligible foreign tourists shopping at stores displaying ''VAT Refund for Tourists'' and meeting stay/departure rules.','Qualifying goods taken out of Thailand by the tourist.','Consumed/non-exported goods and excluded categories; certain high-value/luxury items need additional inspection.','Goods generally must be taken out of Thailand within 60 days from purchase.','Request the P.P.10 VAT refund form and tax invoice at a participating store.','Customs inspection is generally before airline check-in; high-value/luxury goods may require re-inspection after passport control.','Refund method depends on amount: cash may be available up to the applicable limit; card/bank draft options apply.',NULL,'Thailand: tourist VAT refund is available at participating ''VAT Refund for Tourists'' stores. Spend at least THB 2,000 including VAT per store per day, request the P.P.10 form, and export the goods within 60 days. Present the goods and documents to Customs before check-in; some luxury goods are checked again after passport control.','Official Thai Revenue Department','https://vrtmap.rd.go.th/gps/en/Conditions.aspx','https://vrtweb.rd.go.th/','2026-09-27','HIGH','NO','Show available + THB 2,000 + customs-before-check-in.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
