INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('TR','TUR','Türkiye','AVAILABLE','VAT','20% standard; 10% reduced for some goods','Participating-operator/country minimum applies; refresh before trip','Eligible nonresident visitors under Turkey''s tourist tax-free rules.','Qualifying goods from participating Tax Free retailers that are exported.','Consumed/non-exported goods and excluded categories.','Follow Turkish Customs/operator export deadline and validation rules.','Ask the participating retailer for a Tax Free form and present passport/eligibility proof.','Present goods and documents to Customs/refund operator at departure before baggage hand-off when required.','Refund operators deduct fees.',NULL,'Türkiye: tourist Tax Free shopping is active through participating retailers/operators. Standard VAT is 20% with a 10% reduced rate on some goods. Ask for the Tax Free form at purchase and keep the goods, passport and receipts for Customs validation at departure. The practical minimum purchase and operator payout vary, so tripto.to should refresh those fields instead of hard-coding them.','Current refund-operator listing; country details require refresh','https://taxfree.weareplanet.com/countries','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM-HIGH','YES','Show available; keep minimum/fees dynamic.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('UG','UGA','Uganda','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Uganda: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('UA','UKR','Ukraine','NO_SCHEME_CONFIRMED',NULL,NULL,NULL,'As of 2026, no classic tourist Tax Free/VAT-refund system for ordinary retail purchases is operating.',NULL,NULL,NULL,'Do not buy on the assumption that ordinary retail tax will be refunded at departure.','No standard nationwide tourist retail tax-refund departure procedure is confirmed.',NULL,NULL,'Ukraine: As of 2026, no classic tourist Tax Free/VAT-refund system for ordinary retail purchases is operating. Ordinary shopping taxes, where applicable, should generally be treated as part of the purchase price. Duty-free airport/port shopping and business/diplomatic refund rules are separate. Recheck local rules before a high-value purchase because local programs can change.','Current official/secondary check','https://visitukraine.today/blog/8427/shopping-in-ukraine-vat-refund-prices-and-what-to-buy',NULL,'2026-09-27','MEDIUM','YES','Show ''No standard tourist refund confirmed'' with update date.','No standard tourist refund confirmed','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('AE','ARE','United Arab Emirates','AVAILABLE','VAT','5%','AED 250 per Tax Free Tag; may include multiple purchases within the same store group on the same day','Eligible overseas tourists, generally age 18+, shopping at retailers registered in the Tourist Refund Scheme.','Eligible goods that remain with the tourist and are exported from the UAE.','Consumed goods; goods not in the tourist''s possession at departure; vehicles, boats and aircraft are excluded under the scheme rules.','Export validation within 90 days of the tax invoice/purchase.','Ask the participating retailer to create the digital tax-free transaction and present passport/travel document.','Validate tax-free transactions at Planet/FTA validation desks or self-service kiosks at designated air/sea/land exit points; present goods if requested.','Current FTA service page: 13% of the VAT amount requested plus AED 3.60 per tax-free transaction is deducted. Card refunds are normally processed after validation; cash is also available subject to limits.',NULL,'United Arab Emirates: tourist VAT refunds are available through the FTA/Planet system. Minimum qualifying spend is AED 250 per Tax Free Tag. Ask for tax-free processing in the shop, keep the goods and invoices, and validate the transaction when leaving the UAE within 90 days. Current FTA fees deduct 13% of the VAT requested plus AED 3.60 per tax-free transaction.','Official UAE Federal Tax Authority','https://tax.gov.ae/en/services/tourist.vat.refunds.aspx','https://tax.gov.ae/en/taxes/Vat/refunds/tourists.aspx','2026-09-27','HIGH','NO','Show available + AED 250 + 90 days + current fee.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('GB','GBR','United Kingdom','AVAILABLE_LIMITED','VAT','20%','No universal minimum; retailer participation required in Northern Ireland','Great Britain: ordinary visitor retail VAT refund was abolished, except goods delivered directly outside the UK. Northern Ireland: eligible visitors normally resident outside NI and the EU may claim through participating retailers.','Northern Ireland: qualifying goods exported from NI/EU; Great Britain: retailer can zero-rate only when goods are delivered directly outside the UK under the applicable rules.','NI exclusions include used goods, services/hotel bills, vehicles, freight/business exports and other listed categories.','Northern Ireland: take goods out of NI and the EU within 3 months of purchase.','NI: get VAT 407(NI) form from a participating retailer. GB: do not expect an airport VAT refund for goods carried in your luggage.','NI: show goods, completed form and receipts to Customs at the point you leave NI/EU; then use retailer/refund provider. GB: no ordinary luggage-based tourist refund.','NI retailer/refund provider may deduct handling fees.',NULL,'United Kingdom: rules differ sharply by region. In Great Britain (England, Scotland and Wales), tourists cannot normally reclaim VAT on goods they carry home; tax-free treatment is generally only possible when the retailer delivers the goods directly outside the UK. In Northern Ireland, eligible visitors who live outside Northern Ireland and the EU may still claim VAT back from participating shops using VAT 407(NI), with export within 3 months.','Official GOV.UK','https://www.gov.uk/tax-on-shopping/taxfree-shopping',NULL,'2026-09-27','HIGH','NO','Always ask/show region: Great Britain vs Northern Ireland.','Available with important limitations','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('US','USA','United States','NO_SCHEME_CONFIRMED',NULL,NULL,NULL,'No nationwide tourist sales-tax refund system. Sales taxes are mainly state/local; limited local programs/exemptions can exist.',NULL,NULL,NULL,'Do not buy on the assumption that ordinary retail tax will be refunded at departure.','No standard nationwide tourist retail tax-refund departure procedure is confirmed.',NULL,NULL,'United States: No nationwide tourist sales-tax refund system. Sales taxes are mainly state/local; limited local programs/exemptions can exist. Ordinary shopping taxes, where applicable, should generally be treated as part of the purchase price. Duty-free airport/port shopping and business/diplomatic refund rules are separate. Recheck local rules before a high-value purchase because local programs can change.','Current official/secondary check','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','MEDIUM','YES','Show ''No standard tourist refund confirmed'' with update date.','No standard tourist refund confirmed','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('UM','UMI','United States Minor Outlying Islands','NOT_APPLICABLE','Not applicable / no ordinary retail tourist system',NULL,NULL,'United States Minor Outlying Islands have no ordinary consumer tourist retail refund system.',NULL,NULL,NULL,'No standard tourist shopping refund flow.','No standard refund flow.',NULL,NULL,'United States Minor Outlying Islands: United States Minor Outlying Islands have no ordinary consumer tourist retail refund system. A normal VAT/GST tourist-refund workflow is therefore not applicable. Any purchases made through expedition, base, ship or concession operators follow their own pricing/tax arrangements.','Jurisdiction characteristics; not a consumer tax-refund destination','https://www.iso.org/iso-3166-country-codes.html',NULL,'2026-09-27','HIGH','NO','Show ''Not applicable'' rather than ''No''.','Not applicable','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('UY','URY','Uruguay','AVAILABLE','VAT','22%','Depends on goods/category and participating Tax Free regime; verify current operator threshold','Nonresident tourists using the official Tax Free regime/eligible foreign payment methods where required.','Products included in the Tax Free regime bought from participating merchants; separate tourist VAT benefits may apply to selected services.','Non-participating purchases and categories outside the regime.','Complete the departure procedure through one of the authorized border/airport/port points.','Use a participating Tax Free merchant and complete the required transaction documentation.','Complete validation/refund at an authorized departure point such as Carrasco, Laguna del Sauce, Montevideo/Colonia ports and listed land crossings.','Partial VAT refund for Tax Free purchases; service-specific tourist VAT reductions can have separate rules and end dates.',NULL,'Uruguay: a year-round Tax Free regime exists for qualifying purchases at participating shops, with validation at designated airports, ports and land crossings. Uruguay also periodically grants separate VAT reductions to nonresident tourists for selected services, but those benefits can have expiry dates. tripto.to should treat the retail Tax Free scheme separately from temporary restaurant/car-rental/service promotions.','Official Uruguay tax/tourism authorities','https://www.gub.uy/direccion-general-impositiva/Beneficiostributarios','https://uruguaynatural.com/es/beneficios/beneficios-para-turistas-no-residentes/','2026-09-27','HIGH','YES','Show retail Tax Free as available; temporary service benefits need expiry-date logic.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('UZ','UZB','Uzbekistan','AVAILABLE','VAT','12%','UZS 300,000 including VAT','Eligible foreign tourists under Uzbekistan Tax Free rules.','Qualifying goods under the national Tax Free scheme; current official guidance excludes food.','Food and other excluded categories.','Claim at the operating international-airport departure process.','Keep eligible receipts/documents needed by the Tax Free system.','Since 1 April 2026, Tax Free service operates at all international airports; expansion to rail/land points is planned separately.','Tourist receives 85% of the refundable VAT amount; operator retains 15%. Cash or card is available; card payment is stated to arrive within up to 3 business days.',NULL,'Uzbekistan: from 1 April 2026, Tax Free service is available at all international airports. Minimum qualifying purchases are UZS 300,000 including VAT. The tourist receives 85% of the refundable VAT amount and the operator keeps 15%. Food is excluded. Keep receipts and complete the airport process when departing.','Official Uzbekistan government/tourism','https://gov.uz/en/uzbektourism/news/view/151193',NULL,'2026-09-27','HIGH','NO','Show available + all international airports from 2026-04-01.','Tax refund available','tripto.to-tax-refund-v1.0',180,'RECOMMENDED');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('VU','VUT','Vanuatu','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Vanuatu: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('VE','VEN','Venezuela, Bolivarian Republic of','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'No reliable current nationwide tourist-retail refund procedure was individually confirmed in this research pass.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Venezuela, Bolivarian Republic of: a reliable current nationwide tourist retail tax-refund procedure was not individually confirmed. Do not assume that ordinary VAT/GST/sales tax is refundable. Before buying specifically for a tax refund, check the local tax/customs authority and ask the retailer whether it participates in an official scheme. Duty-free airport or port shopping is separate from a post-purchase tourist tax refund.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Show as ''Check local rules'' rather than ''No refund''.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('VN','VNM','Viet Nam','AVAILABLE','VAT','10% standard under current law; category rates vary','VND 2,000,000 at the same refund-eligible business on the same day','Eligible foreign visitors buying goods at VAT-refund businesses.','Unused goods bought from participating VAT-refund businesses and exported through authorized checkpoints.','Consumed/non-exported goods and excluded categories.','Invoice/purchase must fall within the legal 60-day window before departure.','Obtain the required invoice/refund declaration from a participating VAT-refund business.','Before departure, present goods and documentation to Customs at an authorized international airport/seaport checkpoint.','Tourist receives 85% of the refundable VAT; the refund bank keeps 15% as service fee.',NULL,'Vietnam: tourist VAT refunds are available on qualifying unused goods bought at participating refund businesses. Spend at least VND 2,000,000 at the same business on the same day, keep the goods and required invoice/refund documents, and export within the legal 60-day window. The tourist receives 85% of the refundable VAT; the refund bank retains 15%.','Current Vietnamese legal framework','https://thuvienphapluat.vn/van-ban/Thue-Phi-Le-Phi/Decree-181-2025-ND-CP-elaboration-of-the-Law-on-Value-Added-Tax-664568.aspx',NULL,'2026-09-27','MEDIUM-HIGH','YES','Show available + VND2m + 85/15 payout.','Tax refund available','tripto.to-tax-refund-v1.0',180,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('VG','VGB','Virgin Islands, British','NO_GENERAL_VAT_GST','No broad VAT/GST (other duties/taxes may apply)',NULL,NULL,'No VAT/general sales tax.',NULL,NULL,NULL,'There is generally no VAT/GST departure refund to request. Check item-specific duties/excise and local retail taxes.','No standard VAT/GST refund process.',NULL,NULL,'Virgin Islands, British: No VAT/general sales tax. Because there is no broad VAT/GST of the usual kind to reclaim, there is generally no tourist departure VAT refund process. This does not mean every purchase is tax-free: customs duty, excise, local levies or sector taxes may still be built into the price.','Current tax-structure cross-check; territory-specific review recommended','https://vatinfo.org/countries-with-no-vat','https://globalrules.org/compare/tax-free-shopping','2026-09-27','MEDIUM','YES','Show ''No VAT/GST refund to claim''; avoid saying ''tax-free country''.','No broad VAT/GST refund to claim','tripto.to-tax-refund-v1.0',90,'YES');
INSERT OR REPLACE INTO tax_refund_country_guides (iso2,iso3,destination,refund_status,tax_type,standard_tax_rate,minimum_purchase,eligibility,eligible_purchases,excluded_purchases,export_deadline,at_purchase,departure_process,refund_method_fees,future_change,traveler_summary,source_quality,source_url_primary,source_url_secondary,last_verified_at,confidence,manual_review_required,app_display_policy,status_label,data_version,stale_after_days,refresh_before_trip) VALUES ('VI','VIR','Virgin Islands, U.S.','VERIFY_LOCAL_RULES','Local VAT/GST/sales/turnover tax rules vary',NULL,NULL,'U.S. Virgin Islands have local tax rules; do not assume U.S. state sales-tax treatment.',NULL,NULL,NULL,'Before relying on a refund, ask the retailer whether an official tourist tax-refund scheme is operating and what documents must be issued at purchase.','Do not promise an airport/border refund unless the local tax or customs authority, or an authorized operator, confirms the procedure.',NULL,NULL,'Virgin Islands, U.S.: U.S. Virgin Islands have local tax rules; do not assume U.S. state sales-tax treatment. A reliable ordinary tourist retail refund workflow was not confirmed for this dataset. tripto.to should not inherit the parent country''s tax-free rules automatically; it should show ''Check local rules'' until a local tax/customs source is verified.','Not individually verified; safe fallback','https://globalrules.org/compare/tax-free-shopping',NULL,'2026-09-27','LOW','YES','Territory-specific rule required; never auto-copy parent country.','Check local rules','tripto.to-tax-refund-v1.0',90,'YES');
